select public.svc_sync_tenant('{"slug":"ap-studio-detailing","name":"AP Studio Detailing","shortName":"AP Studio","kind":"detailing","tagline":"Car detailing w Katowicach – przy Twoim aucie pracuje sam właściciel","description":"Dzień dobry, nazywam się Aleksander i zajmuję się car detailingiem od 2013 roku, a zawodowo od 2016 – zawsze w najlepszych studiach na najwyższym poziomie. Mam liczne certyfikaty, m.in. 4Nano Polska i CarbonQ Polska. Przy Państwa samochodzie zawsze pracuje zaangażowany właściciel studia, który firmuje efekt własnym nazwiskiem. Każde auto opuszczające moje studio ma być perfekcyjne.","locale":"pl-PL","timezone":"Europe/Warsaw","currency":"PLN","accentColor":"#F4A81D","contacts":{"phone":"+48798171232","address":"ul. Szewska 26A, 40-649 Katowice","mapUrl":"https://www.google.com/maps/search/?api=1&query=Szewska%2026A%2C%2040-649%20Katowice","instagram":"apstudio_detailing","facebook":"StudioDetailingu","email":"biuro.apstudio@gmail.com"},"images":{"hero":"/s/ap-studio-detailing/media/hero.webp","logo":"/s/ap-studio-detailing/media/logo.png"},"hours":{"mon":[["09:00","17:00"]],"tue":[["09:00","17:00"]],"wed":[["09:00","17:00"]],"thu":[["09:00","17:00"]],"fri":[["09:00","17:00"]],"sat":[["09:00","14:00"]],"sun":[]},"closedDates":["2026-11-01","2026-11-11","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-01-06","2027-03-28","2027-03-29","2027-05-01","2027-05-03","2027-05-16","2027-05-27","2027-08-15","2027-11-01","2027-11-11","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":1440,"horizonDays":60,"cancelCutoffHours":24,"defaultBufferMinutes":60},"resources":[{"key":"stanowisko","name":"Stanowisko"}],"services":[{"key":"mycie","name":"Mycie detailingowe","description":"Dekontaminacja i deironizacja, pre-wash pianą o neutralnym pH, mycie ręczne na dwa wiadra, pędzelkowanie zakamarków, glinkowanie lakieru i szyb, wydmuchanie wody, dressingi i mycie szyb.","category":"Mycie i wnętrze","price":300,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"wnetrze","name":"Detailingowe czyszczenie wnętrza","description":"Kompleksowe czyszczenie wnętrza.","category":"Mycie i wnętrze","price":600,"priceFrom":true,"durationMinutes":360,"resources":["stanowisko"]},{"key":"pranie","name":"Pranie tapicerki","description":"Pranie tapicerki materiałowej.","category":"Mycie i wnętrze","price":400,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"tapicerka","name":"Zabezpieczanie tapicerki","description":"Impregnacja chroniąca tapicerkę.","category":"Mycie i wnętrze","price":400,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"skory","name":"Renowacja skór","description":"Cena do ustalenia indywidualnie.","category":"Mycie i wnętrze","price":0,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]},{"key":"one-step","name":"Jednoetapowa korekta lakieru (One-Step)","description":"Odświeżenie lakieru – usuwamy do 65% zarysowań w jednym etapie.","category":"Korekta i polerowanie","price":800,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"korekta-2","name":"Dwuetapowa korekta lakieru","description":"Głębsza korekta zarysowań i zmatowień.","category":"Korekta i polerowanie","price":1200,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"korekta-pelna","name":"Pełna korekta lakieru","description":"3–5 etapów polerowania – usuwa do 95% niedoskonałości.","category":"Korekta i polerowanie","price":2000,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"szyby","name":"Polerowanie szyb","description":"Usuwanie rys i zmatowień szyb.","category":"Korekta i polerowanie","price":500,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"reflektory","name":"Polerowanie reflektorów","description":"Przywrócenie przejrzystości reflektorów.","category":"Korekta i polerowanie","price":300,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"ppf-basic","name":"Folia PPF – pakiet basic","description":"Zderzak przedni i reflektory. Cena 1000–1800 zł.","category":"Folie PPF i kolor","price":1000,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"ppf-full-front","name":"Folia PPF – pakiet full front","description":"Zderzak przedni, reflektory, maska, przednie błotniki, lusterka, słupki A, czoło dachu, wnęki pod klamkami i próg załadunkowy. Cena 4500–7000 zł.","category":"Folie PPF i kolor","price":4500,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ppf-cale","name":"Folia PPF – całe auto","description":"Oklejenie całego samochodu bezbarwną folią PPF.","category":"Folie PPF i kolor","price":10000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"ppf-mat","name":"Matowa folia PPF – całe auto","description":"Zmiana wykończenia na mat z ochroną lakieru.","category":"Folie PPF i kolor","price":12000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"kolor","name":"Zmiana koloru całego auta","description":"Zmiana koloru folią do stylizacji.","category":"Folie PPF i kolor","price":8000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"kolor-ppf","name":"Zmiana koloru kolorową folią PPF","description":"Nowy kolor i ochrona lakieru w jednym.","category":"Folie PPF i kolor","price":16000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"ceramika-1","name":"Roczna powłoka ceramiczna","description":"Powłoki 4nano Polska.","category":"Powłoki ceramiczne","price":1000,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"ceramika-2","name":"Dwuletnia powłoka ceramiczna","description":"Powłoki 4nano Polska.","category":"Powłoki ceramiczne","price":1600,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ceramika-3","name":"Trzyletnia powłoka ceramiczna","description":"Powłoki 4nano Polska.","category":"Powłoki ceramiczne","price":2000,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ceramika-5","name":"Pięcioletnia powłoka ceramiczna","description":"Powłoki 4nano Polska.","category":"Powłoki ceramiczne","price":2600,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"felgi","name":"Powłoka ceramiczna na felgi","description":"Zabezpieczenie felg.","category":"Powłoki ceramiczne","price":400,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"szyby-kwarc","name":"Powłoka kwarcowa na szyby","description":"Hydrofobowe zabezpieczenie szyb.","category":"Powłoki ceramiczne","price":300,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"cabrio","name":"Zabezpieczenie dachu cabrio","description":"Impregnacja miękkiego dachu.","category":"Powłoki ceramiczne","price":400,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]}],"infoCards":[{"icon":"medal","title":"Pracuje sam właściciel","text":"Aleksander firmuje każdy efekt własnym nazwiskiem – w detailingu od 2013 roku."},{"icon":"shield","title":"Certyfikaty","text":"CarbonQ, PremiumShield Polska, Wrapster i powłoki 4nano Polska."},{"icon":"sparkle","title":"Darmowa wycena","text":"Przy łączeniu usług możliwa negocjacja ceny."}],"gallery":[{"image":"/s/ap-studio-detailing/media/work-gt3rs.webp","caption":"Porsche 911 GT3 RS"},{"image":"/s/ap-studio-detailing/media/work-model-y.webp","caption":"Tesla Model Y – zmiana koloru matową bezbarwną folią ochronną"},{"image":"/s/ap-studio-detailing/media/work-wrangler.webp","caption":"Jeep Wrangler Rubicon"},{"image":"/s/ap-studio-detailing/media/work-f-pace.webp","caption":"Jaguar F-Pace SVR"},{"image":"/s/ap-studio-detailing/media/work-lbx.webp","caption":"Lexus LBX"},{"image":"/s/ap-studio-detailing/media/work-xc90.webp","caption":"Volvo XC90"},{"image":"/s/ap-studio-detailing/media/work-c-klasa.webp","caption":"Mercedes-Benz klasy C"},{"image":"/s/ap-studio-detailing/media/work-bmw.webp","caption":"BMW serii 6 Gran Turismo"},{"image":"/s/ap-studio-detailing/media/work-megane.webp","caption":"Renault Mégane R.S."},{"image":"/s/ap-studio-detailing/media/work-golf.webp","caption":"Volkswagen Golf"},{"image":"/s/ap-studio-detailing/media/work-sportage.webp","caption":"Kia Sportage"},{"image":"/s/ap-studio-detailing/media/work-126p.webp","caption":"Fiat 126p"},{"image":"/s/ap-studio-detailing/media/work-aleksander.webp","caption":"Aleksander – właściciel AP Studio"}],"faq":[{"question":"Czym różni się mycie detailingowe od zwykłej myjni?","answer":"To bezpieczny, wieloetapowy proces: dekontaminacja i deironizacja, pre-wash pianą o neutralnym pH, mycie ręczne na dwa wiadra z separatorami, pędzelkowanie zakamarków, glinkowanie lakieru i szyb, suszenie mikrofibrą, wydmuchanie wody sprężonym powietrzem i dressingi. Tak przygotowany lakier jest gotowy do wosku lub korekty.","keywords":["myjni","roznic","skad taka cena","mycie detailingowe"]},{"question":"Czym różni się One-Step od pełnej korekty?","answer":"One-Step to jeden etap polerowania, który usuwa do 65% zarysowań. Pełna korekta to 3–5 etapów polerowania – usuwa nawet do 95% niedoskonałości lakieru.","keywords":["one step","onestep","pelna korekt","roznic","odswiez"]},{"question":"Kiedy najlepiej okleić auto folią PPF?","answer":"Najlepiej zaraz po odbiorze auta z salonu albo przy bardzo niskim przebiegu – każdy defekt lakieru, np. odprysk, byłby pod folią jeszcze bardziej widoczny.","keywords":["kiedy","ppf","folia","salon","okleic"]},{"question":"Jakie jest najlepsze zabezpieczenie samochodu?","answer":"Najlepiej sprzedającym się połączeniem jest folia PPF na najbardziej narażone elementy i powłoka ceramiczna na resztę karoserii. Pracujemy na foliach Premium Shield i Clif Design oraz powłokach 4nano Polska.","keywords":["najlepsze","zabezpiecz","polaczen","co wybrac"]},{"question":"Czy można negocjować cenę?","answer":"Tak, przy łączeniu usług istnieje możliwość negocjacji ceny. Wycena jest darmowa – odwiedź nas, zadzwoń lub napisz.","keywords":["negocj","rabat","taniej","wycen","laczen"]},{"question":"Gdzie was znajdę?","answer":"Katowice, ul. Szewska 26A. Telefon +48 798 171 232.","keywords":["gdzie","adres","szewsk","dojazd"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '7213103974551b363d3c8818f1a8956dde8bc5c5886c2a2cd472cd679dd678e6', true);
