select public.svc_sync_tenant('{"slug":"art-detailing-bydgoszcz","name":"ART Detailing Bydgoszcz","shortName":"ART Detailing","kind":"detailing","tagline":"Zabezpieczenie nowych aut oraz renowacja lakieru i skór – od 2014 roku","description":"ART Detailing powstał w 2014 roku z zamiłowania do motoryzacji. Na czas usługi Twoje auto staje się naszym „oczkiem w głowie” – poświęcamy mu czas, umiejętności i wiedzę zdobywaną w kraju i za granicą. Specjalizujemy się w zabezpieczaniu nowych aut (powłoki ochronne i folie PPF) oraz renowacji lakieru i skór. Od 2023 roku w dziale ART ANTICOR wykonujemy też zabezpieczenia antykorozyjne podwozi szwajcarskim Waxoyl.","locale":"pl-PL","timezone":"Europe/Warsaw","currency":"PLN","accentColor":"#5B2A86","contacts":{"phone":"+48602152322","address":"ul. Szczecińska 10, 86-065 Lisi Ogon k/Bydgoszczy","facebook":"https://www.facebook.com/artdetailingbydgoszcz","email":"studio@artdetailing.pl"},"images":{"hero":"/s/art-detailing-bydgoszcz/media/hero.webp","logo":"/s/art-detailing-bydgoszcz/media/logo.png"},"hours":{"mon":[["07:30","17:00"]],"tue":[["07:30","17:00"]],"wed":[["07:30","17:00"]],"thu":[["07:30","17:00"]],"fri":[["07:30","17:00"]],"sat":[["10:00","14:00"]],"sun":[]},"closedDates":["2026-11-01","2026-11-11","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-01-06","2027-03-28","2027-03-29","2027-05-01","2027-05-03","2027-05-16","2027-05-27","2027-08-15","2027-11-01","2027-11-11","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":720,"horizonDays":60,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"stanowisko","name":"Stanowisko"}],"services":[{"key":"mini","name":"Detailing Mini","description":"Dekontaminacja, glinkowanie, mycie, jednoetapowe polerowanie One Step i wosk, niewidzialna wycieraczka, odkurzanie i dressing wnętrza, wosk na felgi. Idealny przed zimą lub na wiosnę. Cena: hatchback 1199 zł, sedan/kombi/crossover 1399 zł, limuzyna/SUV/Van 1599 zł.","ca