,"durationMinutes":180,"resources":["stanowisko"]},{"key":"mycie-detailingowe","name":"Mycie Detailingowe","description":"Dekontaminacja i deironizacja, dwa mycia z Grit Guard, glinkowanie, wnęki parą, bezdotykowe osuszanie, wosk syntetyczny na 2 miesiące, wnętrze i zapach. Środki DURAGLOSS. Auto zabezpieczone u nas: 399 zł. Cena: hatchback 499 zł, sedan/kombi/crossover 499 zł, limuzyna/SUV/Van 599 zł.","category":"Mycie","price":499,"priceFrom":true,"durationMinutes":300,"resources":["stanowisko"]},{"key":"wosk","name":"Woskowanie lakieru woskiem syntetycznym","description":"Trwały wosk syntetyczny – ochrona powyżej 6 miesięcy.","category":"Mycie","price":249,"priceFrom":false,"durationMinutes":90,"resources":["stanowisko"]},{"key":"silnik-para","name":"Kosmetyka parowa komory silnika","description":"Mycie parowe komory silnika.","category":"Mycie","price":99,"priceFrom":false,"durationMinutes":60,"resources":["stanowisko"]},{"key":"silnik-chemia","name":"Mycie chemiczne komory silnika","description":"Chemiczne mycie komory silnika.","category":"Mycie","price":199,"priceFrom":false,"durationMinutes":90,"resources":["stanowisko"]},{"key":"odkurzanie","name":"Odkurzanie i odświeżenie wnętrza","description":"Odkurzanie, plastiki Interior QD, wyświetlacze, szyby z obu stron i wnęki drzwi.","category":"Wnętrze","price":149,"priceFrom":false,"durationMinutes":120,"resources":["stanowisko"]},{"key":"pranie","name":"Pranie ekstrakcyjne tapicerki","description":"Pranie ekstrakcyjne, szyby, osuszanie i zapach. Opcje: podsufitka bonetem +149 zł, pasy bezpieczeństwa +200 zł / 4 pasy. Cena: hatchback 499 zł, sedan/kombi/crossover 499 zł, limuzyna/SUV/Van 599 zł.","category":"Wnętrze","price":499,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"wnetrze-max","name":"Detailing wnętrza Max – materiał","description":"Z demontażem przednich foteli: pranie całości, dressing AQUA, wyświetlacze, wnęki parą z woskiem, uszczelki, osuszanie i zapach perfumowy. Cena: hatchback 1199 zł, sedan/kombi/crossover 1399 zł, limuzyna/SUV/Van 1499 zł.","category":"Wnętrze","price":1199,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"impregnacja","name":"Impregnacja tapicerki materiałowej","description":"Zabezpieczenie tapicerki przed plamami i wilgocią. Cena: hatchback 399 zł, sedan/kombi/crossover 399 zł, limuzyna/SUV/Van 499 zł.","category":"Wnętrze","price":399,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"ozon","name":"Ozonowanie wnętrza","description":"Dezynfekcja i neutralizacja zapachów ozonem.","category":"Wnętrze","price":99,"priceFrom":false,"durationMinutes":60,"resources":["stanowisko"]},{"key":"skora","name":"Czyszczenie i impregnacja skór","description":"Odkurzanie, plastiki, wyświetlacze, szyby, wnęki parą i impregnacja wszystkich skór Colourlock. Powtórnie w ciągu 12 miesięcy: 300 zł. Cena: hatchback 499 zł, sedan/kombi/crossover 499 zł, limuzyna/SUV/Van 599 zł.","category":"Wnętrze","price":499,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"skora-max","name":"Detailing wnętrza Max – skóra","description":"Z demontażem przednich foteli, płukaniem tkanin z neutralizatorem zapachów i impregnacją wszystkich skór Colourlock. Cena: hatchback 1199 zł, sedan/kombi/crossover 1399 zł, limuzyna/SUV/Van 1499 zł.","category":"Wnętrze","price":1199,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"renowacja-skory","name":"Renowacja tapicerki skórzanej","description":"Czyszczenie, usuwanie rys i zagnieceń, dobór barwy i lakierowanie Colourlock. Komplet (fotele, boczki, zagłówki, kierownica) od 2999 zł, komplet foteli od 1999 zł, fotel od 999 zł, boczek od 599 zł.","category":"Wnętrze","price":2999,"priceFrom":true,"durationMinutes":4320,"resources":["stanowisko"]},{"key":"kierownica","name":"Renowacja kierownicy i gałki biegów","description":"Renowacja skóry kierownicy i gałki skrzyni biegów systemem Colourlock.","category":