vrstva, která ještě zvýší lesk a hydrofobní vlastnosti laku. SUV příplatek +1000 Kč.","category":"Exteriér a keramika","price":6000,"priceFrom":false,"durationMinutes":240,"resources":["tym"]},{"key":"lesteni-1","name":"Jednokrokové leštění laku","description":"Oživení hloubky laku, vyšší lesk, odstranění 50–60 % škrábanců. Včetně umytí, odmaštění a přípravy na vosk či keramiku. SUV příplatek +1000 Kč.","category":"Leštění laku","price":5000,"priceFrom":false,"durationMinutes":480,"resources":["tym"]},{"key":"lesteni-2","name":"Dvoukrokové leštění laku","description":"Odstranění 70–80 % škrábanců. SUV příplatek +1000 Kč.","category":"Leštění laku","price":7000,"priceFrom":false,"durationMinutes":600,"resources":["tym"]},{"key":"lesteni-3","name":"Tříkrokové leštění laku","description":"Abrazivní, střední a finišovací krok – odstranění 95 % škrábanců. SUV příplatek +1000 Kč.","category":"Leštění laku","price":9000,"priceFrom":false,"durationMinutes":1440,"resources":["tym"]},{"key":"svetla","name":"Leštění světlometů (za kus)","description":"Leštění světlometu, cena od 1 000 Kč za kus.","category":"Leštění laku","price":1000,"priceFrom":true,"durationMinutes":60,"resources":["tym"]},{"key":"karavan","name":"Karavan komplet","description":"Kompletní čištění a tepování interiéru karavanu včetně lůžek, kuchyňky a koupelny a dezinfekce ozonem. Cena se může lišit dle velikosti a míry znečištění auta.","category":"Karavany a kamiony","price":8490,"priceFrom":false,"durationMinutes":600,"resources":["tym"]},{"key":"kamion","name":"Tahač / kamion","description":"Kompletní čištění kabiny tahače včetně lůžek, kuchyňky, úložných boxů a dezinfekce ozonem. Cena se může lišit dle velikosti a míry znečištění auta.","category":"Karavany a kamiony","price":4500,"priceFrom":false,"durationMinutes":360,"resources":["tym"]}],"infoCards":[{"icon":"car","title":"Přijedeme k vám","text":"Po Praze je doprava v ceně, modré zóny nejsou překážkou – máme i vlastní elektrocentrálu."},{"icon":"clock","title":"Šetříme váš čas","text":"Auto vyčistíme, zatímco jste v práci nebo na schůzce."},{"icon":"drop","title":"Nejlepší prostředky","text":"Koch Chemie, Auto Finesse a další špičkové čisticí a ochranné prostředky."}],"gallery":[{"image":"/s/auto-v-cistote/media/work-sedadla-after.webp","before":"/s/auto-v-cistote/media/work-sedadla-before.webp","caption":"Přední sedadla a podlaha – před a po"},{"image":"/s/auto-v-cistote/media/work-ridic-after.webp","before":"/s/auto-v-cistote/media/work-ridic-before.webp","caption":"Místo řidiče – před a po"},{"image":"/s/auto-v-cistote/media/work-kufr-after.webp","before":"/s/auto-v-cistote/media/work-kufr-before.webp","caption":"Zavazadlový prostor – před a po"},{"image":"/s/auto-v-cistote/media/work-palubka-after.webp","before":"/s/auto-v-cistote/media/work-palubka-before.webp","caption":"Palubní deska a středový tunel – před a po"},{"image":"/s/auto-v-cistote/media/work-superb-after.webp","before":"/s/auto-v-cistote/media/work-superb-before.webp","caption":"Interiér Škoda Superb – před a po"},{"image":"/s/auto-v-cistote/media/work-kufr-2-after.webp","before":"/s/auto-v-cistote/media/work-kufr-2-before.webp","caption":"Kufr plný sena – před a po"},{"image":"/s/auto-v-cistote/media/work-zadni-after.webp","before":"/s/auto-v-cistote/media/work-zadni-before.webp","caption":"Zadní sedačka – před a po"},{"image":"/s/auto-v-cistote/media/work-mobil.webp","caption":"Mobilní čištění přímo u zákazníka"},{"image":"/s/auto-v-cistote/media/work-bmw-e30.webp","caption":"BMW řady 3 (E30)"}],"faq":[{"question":"Kam za mnou přijedete?","answer":"Jsme plně mobilní a přijedeme na vámi zvolené místo. Po Praze je doprava v ceně, modré zóny nejsou překážkou a v případě potřeby si elektřinu vyrobíme vlastní elektrocentrálou. Stačí jen dostatečné místo na práci.","keywords":["kam","kde","prijedete","mobilni","doprava","praha","zona","elektr"]},{"question":"Platí ceny i pro SUV?","answer":"Ceny čištění interiéru jsou stejné pro všechny osobní auta i SUV do 5 sedadel, 7místné vozy mají příplatek 700 Kč. U keramiky a leštění je u SUV příplatek 1 000–2 000 Kč.","keywords":["suv","7mist","sedmimist","priplat","velikost"]},{"question":"Čistíte i sedačky a koberce doma?","answer":"Ano, umíme vyčistit i koberce, sedačky, gauče a křesla. Cenu domluvíme po telefonu.","keywords":["koberc","sedack","gauc","kresl","doma"]},{"question":"Nabízíte dárkové poukazy?","answer":"Ano, dárkové poukazy v hodnotě 1 000 až 10 000 Kč. Ozvěte se na +420 604 422 412.","keywords":["poukaz","voucher","darek","darkov"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '0670287c903413abb31bb896c91473679f4ae9f0bc5dbc10a8532c703eb93926', true);
