ionMinutes":120,"resources":["stanowisko"]},{"key":"mycie-qd","name":"Mycie + Quick Detailer ceramiczny","description":"Mycie samochodu uzupełnione quick detailerem z wiązkami ceramicznymi.","category":"Mycie","price":250,"priceFrom":true,"durationMinutes":150,"resources":["stanowisko"]},{"key":"mycie-powloka","name":"Mycie auta z powłoką lub woskiem twardym","description":"Premium chemia regenerująca zabezpieczenie – dla aut z powłoką ceramiczną, kwarcową lub woskiem.","category":"Mycie","price":250,"priceFrom":true,"durationMinutes":150,"resources":["stanowisko"]},{"key":"mycie-wnetrze","name":"Mycie oraz sprzątanie wnętrza","description":"Mycie ręczne i sprzątanie wnętrza.","category":"Mycie","price":400,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"detailing-wnetrza","name":"Detailing wnętrza","description":"Pranie ekstrakcyjne tapicerki, podłogi i bagażnika, skóry produktami o neutralnym pH, dokładne czyszczenie plastików.","category":"Wnętrze i skóra","price":1000,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"pranie","name":"Pranie tapicerki materiałowej","description":"Ekstrakcyjne pranie tapicerki materiałowej.","category":"Wnętrze i skóra","price":400,"priceFrom":true,"durationMinutes":360,"resources":["stanowisko"]},{"key":"skora","name":"Czyszczenie tapicerki skórzanej","description":"Oczyszczanie skóry produktami dopasowanymi do jej kondycji.","category":"Wnętrze i skóra","price":500,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"skora-retro","name":"Czyszczenie tapicerki skórzanej retro","description":"Delikatne czyszczenie skór w autach klasycznych.","category":"Wnętrze i skóra","price":600,"priceFrom":true,"durationMinutes":300,"resources":["stanowisko"]},{"key":"skora-nawilzanie","name":"Nawilżanie tapicerki skórzanej","description":"Przywrócenie elastyczności skóry.","category":"Wnętrze i skóra","price":200,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"skora-zabezpieczenie","name":"Zabezpieczenie z nawilżeniem skóry","description":"Nawilżenie i zabezpieczenie tapicerki skórzanej.","category":"Wnętrze i skóra","price":300,"priceFrom":true,"durationMinutes":90,"resources":["stanowisko"]},{"key":"skora-przebarwienia","name":"Zabezpieczenie skóry przed przebarwieniami","description":"Ochrona przed przebarwieniami od dżinsów i innych materiałów.","category":"Wnętrze i skóra","price":200,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"skora-barwnik","name":"Renowacja barwnika skóry","description":"Odnowienie barwnika z bezbarwną powłoką ochronną. Z naprawą zarysowań i uszkodzeń od 250 zł.","category":"Wnętrze i skóra","price":200,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"skora-plamy","name":"Usuwanie przebarwień i śladów po długopisie","description":"Punktowe usuwanie plam ze skóry.","category":"Wnętrze i skóra","price":150,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"cabrio","name":"Konserwacja dachu cabrio","description":"Oczyszczenie i zabezpieczenie dachu – także starych, zniszczonych.","category":"Wnętrze i skóra","price":600,"priceFrom":true,"durationMinutes":360,"resources":["stanowisko"]},{"key":"korekta-oczyszczajaca","name":"Korekta oczyszczająca","description":"Maszynowe dogłębne oczyszczenie lakieru – idealny krok przed woskowaniem.","category":"Korekta lakieru","price":1100,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"korekta-one-step","name":"Korekta One Step","description":"Oczyszczenie, część korekty i powłoka ochronna na 12 miesięcy. Usuwa 30–50% zarysowań.","category":"Korekta lakieru","price":1300,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"korekta-1","name":"Korekta jednoetapowa","description":"Usuwa małe i mikro zarysowania – 50–60%. Cena zależy od wielkości auta.","category":"Korekta lakieru","price":1600,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"korekta-2","name":"Korekta dwuetapowa","description":"Lakier odzyskuje głębię i blask bez smug i hologramów. Usuwa 60–80% zarysowań.","category":"Korekta lakieru","price":1800,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"korekta-pelna","name":"Pełna korekta lakieru","description":"Usuwa 80–90% zarysowań. W cenie korekty woskowanie Swissvax Onyx.","category":"Korekta lakieru","price":2100,"priceFrom":true,"durationMinutes":4320,"resources":["stanowisko"]},{"key":"lakierowanie","name":"Lakierowanie elementów karoserii","description":"Lakierowanie pojedynczych elementów.","category":"Korekta lakieru","price":1200,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ceramika-2","name":"Powłoka ceramiczna do 2 lat","description":"Trwałość 12–24 miesiące, do 30 tys. km – idealna do miasta. Auto używane z korektą jednoetapową w cenie – drożej o 1000 zł. Ceny dla średnich gabarytów, pisemna gwarancja producenta i studia.","category":"Powłoki","price":1500,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ceramika-3","name":"Powłoka ceramiczna do 3 lat","description":"Trwałość 24–36 miesięcy, do 50 tys. km – miasto i trasa. Auto używane z korektą jednoetapową w cenie – drożej o 1000 zł. Ceny dla średnich gabarytów, pisemna gwarancja producenta i studia.","category":"Powłoki","price":2200,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ceramika-5","name":"Powłoka ceramiczna do 5 lat","description":"Trwałość 48–60 miesięcy, 60–100 tys. km, wzmocniona ochrona UV, warstwa do 10 mikronów. Auto używane z korektą jednoetapową w cenie – drożej o 1000 zł. Ceny dla średnich gabarytów, pisemna gwarancja producenta i studia.","category":"Powłoki","price":3500,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"graphene-3","name":"Powłoka graphene do 2–3 lat","description":"Jedna warstwa, do 40 tys. km. Nano-rurki węglowe z elastomerami – samoregeneracja mikrorys. Auto używane z korektą jednoetapową w cenie – drożej o 1000 zł. Ceny dla średnich gabarytów, pisemna gwarancja producenta i studia.","category":"Powłoki","price":2200,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"graphene-5","name":"Powłoka graphene do 5 lat / 60 tys. km","description":"Dwie warstwy, samoregeneracja, lustrzany efekt. Auto używane z korektą jednoetapową w cenie – drożej o 1000 zł. Ceny dla średnich gabarytów, pisemna gwarancja producenta i studia.","category":"Powłoki","price":2800,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"graphene-5-plus","name":"Powłoka graphene do 5 lat / 100 tys. km","description":"Dwie warstwy z systemem antygraffiti. Auto używane z korektą jednoetapową w cenie – drożej o 1000 zł. Ceny dla średnich gabarytów, pisemna gwarancja producenta i studia.","category":"Powłoki","price":3500,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"szyba","name":"Powłoka hydrofobowa – szyba czołowa","description":"Trwałość 6–8 miesięcy. Komplet szyb od 600 zł (boczne do 2 lat).","category":"Powłoki","price":150,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"felgi","name":"Zabezpieczenie felg powłoką SiCN","description":"Komplet 4 felg z dodatkiem graphenu. Felgi używane od 1000 zł.","category":"Powłoki","price":800,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"wosk-twardy","name":"Wosk twardy","description":"Woski premium (m.in. Fireball) o trwałości do 3 miesięcy. Sealant do 6–8 miesięcy od 600 zł, wosk show car do 8–12 miesięcy od 800 zł.","category":"Woski","price":500,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"swissvax","name":"Wosk Swissvax z przygotowaniem","description":"Woski dedykowane markom (Porsche, Mercedes, BMW, Ferrari, Volvo, Lexus…) i lakierom matowym – od 500 do 1500 zł zależnie od wosku (30–81% carnauby).","category":"Woski","price":500,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"swissvax-felgi","name":"Wosk Swissvax na felgi","description":"Komplet felg – połysk i ochrona przed pyłem z klocków. Linie premium od 1000 zł.","category":"Woski","price":500,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"swissvax-wnetrze","name":"Pielęgnacja wnętrza Swissvax","description":"Leather Cleaner & Milk, Leather Glaze, Protection na plastiki, Wood Polish – od 200 zł; skóry w autach kolekcjonerskich od 600 zł.","category":"Woski","price":200,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"folia-mycie","name":"Mycie oklejonego samochodu","description":"Mycie z chemią o neutralnym pH dla folii kolorowej i PPF.","category":"Folie","price":250,"priceFrom":true,"durationMinutes":150,"resources":["stanowisko"]},{"key":"folia-mycie-detailing","name":"Mycie detailingowe oklejonego samochodu","description":"Wieloetapowe mycie oczyszczające z deironizacją.","category":"Folie","price":500,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"folia-korekta","name":"Korekta oczyszczająca folii kolor i PPF","description":"Usuwa zabrudzenia biologiczne, osady wapienne i drobne rysy, odświeża barwę folii.","category":"Folie","price":1000,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"folia-sio2","name":"Podstawowe zabezpieczenie folii SiO2","description":"Szybka powłoka samoczyszcząca na folię.","category":"Folie","price":350,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"folia-wosk","name":"Zabezpieczenie folii woskiem twardym","description":"Dedykowany wosk na folię kolorową i PPF.","category":"Folie","price":800,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"folia-kwarc","name":"Powłoka kwarcowa na folię","description":"Powłoka membranowa wypełniająca pory folii. Wersja Kwarc+ od 2000 zł.","category":"Folie","price":1500,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"suchy-lod","name":"Czyszczenie suchym lodem","description":"Stawka od 800 zł/h – np. komplet pasów bezpieczeństwa od 500 zł, komora silnika od 1000 zł.","category":"Dodatkowe","price":800,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]}],"infoCards":[{"icon":"medal","title":"Od 2006 roku","text":"Doświadczenie zdobyte w Hamburgu, studio w Gdyni od 2012."},{"icon":"shield","title":"Fireball i FX Protect","text":"Akredytowane studio powłok – gwarancja na cały okres trwałości."},{"icon":"sparkle","title":"Swissvax Car Care Center","text":"Certyfikowane woski dedykowane marce Twojego auta."}],"gallery":[{"image":"/s/car-detailing-studio-gdynia/media/work-amg-gt.webp","caption":"Mercedes-AMG GT – powłoka FX Protect"},{"image":"/s/car-detailing-studio-gdynia/media/work-amg-gt-przod.webp","caption":"Mercedes-AMG GT – przód"},{"image":"/s/car-detailing-studio-gdynia/media/work-hydrofob.webp","caption":"Efekt hydrofobowy powłoki Hypernity"},{"image":"/s/car-detailing-studio-gdynia/media/work-rs6-bok.webp","caption":"Audi RS6 – powłoka ceramiczna"},{"image":"/s/car-detailing-studio-gdynia/media/work-rs6-tyl.webp","caption":"Audi RS6 – tył"},{"image":"/s/car-detailing-studio-gdynia/media/work-rs6-przod.webp","caption":"Audi RS6 – przód"},{"image":"/s/car-detailing-studio-gdynia/media/work-rs6-felga.webp","caption":"Audi RS6 – felgi i reflektory"},{"image":"/s/car-detailing-studio-gdynia/media/work-rs6-badge.webp","caption":"Audi RS6 – detal"},{"image":"/s/car-detailing-studio-gdynia/media/work-fiat.webp","caption":"Fiat 500 – korekta lakieru"},{"image":"/s/car-detailing-studio-gdynia/media/work-fiat-wosk.webp","caption":"Fiat 500 – aplikacja wosku"},{"image":"/s/car-detailing-studio-gdynia/media/work-korekta.webp","caption":"Ocena lakieru pod lampą"},{"image":"/s/car-detailing-studio-gdynia/media/work-felga.webp","caption":"Audi – felga po zabezpieczeniu"},{"image":"/s/car-detailing-studio-gdynia/media/work-silnik.webp","caption":"Komora silnika po czyszczeniu"},{"image":"/s/car-detailing-studio-gdynia/media/work-fireball.webp","caption":"Woski Fireball w naszym studiu"}],"faq":[{"question":"Jak wyceniacie usługi?","answer":"Każdą usługę wyceniamy dokładnie na miejscu, po oględzinach auta. Ceny na stronie są cenami „od” dla aut o średnich gabarytach.","keywords":["wycen","ile kosztuj","cennik","koszt"]},{"question":"Ile kosztuje powłoka na auto używane?","answer":"Dla aut używanych w cenie powłoki jest korekta jednoetapowa – to zwykle około 1000 zł więcej niż dla nowego auta, np. ceramika do 2 lat od 2500 zł zamiast od 1500 zł.","keywords":["uzywan","nowe auto","nowego"]},{"question":"Czy powłoka ma gwarancję?","answer":"Tak. Każda powłoka ma pisemną gwarancję producenta i naszego studia na cały okres trwałości. Serwis powłoki robimy raz w roku – przypominamy o nim przez cały okres.","keywords":["gwaranc","serwis powlok","przeglad"]},{"question":"Czym różni się graphene od ceramiki?","answer":"Powłoka graphene zawiera nano-rurki węglowe z elastomerami: warstwa jest dwukrotnie grubsza, mikrorysy samoregenerują się w cieple, a połysk i hydrofobowość są wyższe.","keywords":["graphene","grafen","rozni","roznic"]},{"question":"Czy w cenie korekty jest zabezpieczenie?","answer":"Tak – po korekcie lakier woskujemy woskiem Swissvax Onyx. Na mocniejsze zabezpieczenie dajemy duży rabat (nie dotyczy powłok ceramicznych).","keywords":["po korekc","onyx","w cenie korekt"]},{"question":"Gdzie jesteście i kiedy otwarte?","answer":"Gdynia, ul. Hutnicza 11. Pon–pt 8:00–17:00.","keywords":["gdzie","adres","hutnicz","dojazd","otwart","godzin"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'a610b866076cf5d3ed2855a7ffe83293f0a3b790bdb3146688a964dc2d7fe4d3', true);
