eFrom":false,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ppf-full-front","name":"Folia PPF – Full Front","description":"Zderzak, maska, reflektory, błotniki i lusterka – maksymalna ochrona przodu auta. Gwarancja 10 lat. Darmowa wycena.","category":"Folie PPF i kolor","price":0,"priceFrom":false,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ppf-full-body","name":"Folia PPF – Full Body","description":"Kompleksowa ochrona całej karoserii. Średnie ceny od kilku do kilkunastu tysięcy złotych za całe nadwozie. Darmowa wycena.","category":"Folie PPF i kolor","price":0,"priceFrom":false,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"ppf-kolor","name":"Kolorowa folia PPF – zmiana koloru","description":"Zmiana koloru i ochrona lakieru w jednym. Pełne oklejenie zwykle 11 000–19 000 zł netto – zależnie od modelu, nadwozia i zakresu.","category":"Folie PPF i kolor","price":11000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"zmiana-koloru","name":"Zmiana koloru auta folią","description":"Alternatywa dla lakierowania pojazdu – całość lub wybrane elementy. Darmowa wycena.","category":"Folie PPF i kolor","price":0,"priceFrom":false,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"kameleon","name":"Folia kameleon na szybę","description":"Odmień wygląd swojego auta folią kameleon. Darmowa wycena.","category":"Folie PPF i kolor","price":0,"priceFrom":false,"durationMinutes":240,"resources":["stanowisko"]},{"key":"ceramika-1","name":"Powłoka ceramiczna (1 rok)","description":"Podstawowe zabezpieczenie lakieru. Cena brutto.","category":"Powłoki i lakier","price":1800,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ceramika-3","name":"Powłoka ceramiczna (3 lata)","description":"Zabezpieczenie lakieru na 3 lata. Darmowa wycena.","category":"Powłoki i lakier","price":0,"priceFrom":false,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ceramika-premium","name":"Pakiet premium – ceramika 5 lat, felgi i szyby","description":"Najbardziej kompleksowa ochrona: lakier na 5 lat, felgi oraz szyby. Cena brutto.","category":"Powłoki i lakier","price":3300,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"korekta","name":"Renowacja i korekta lakieru","description":"Usuwanie rys i przebarwień – lakier odzyskuje świeży wygląd i blask. Darmowa wycena.","category":"Powłoki i lakier","price":0,"priceFrom":false,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"wosk","name":"Aplikacja twardego wosku","description":"Ochrona i połysk lakieru. Darmowa wycena.","category":"Powłoki i lakier","price":0,"priceFrom":false,"durationMinutes":180,"resources":["stanowisko"]},{"key":"reflektory","name":"Regeneracja reflektorów","description":"Polerowanie matowych reflektorów. Darmowa wycena.","category":"Powłoki i lakier","price":0,"priceFrom":false,"durationMinutes":120,"resources":["stanowisko"]},{"key":"grafiki","name":"Grafiki na auto","description":"Wyróżnij się na drodze – projekt i aplikacja grafik. Proste grafiki 1–3 godziny. Darmowa wycena.","category":"Grafika i reklama","price":0,"priceFrom":false,"durationMinutes":180,"resources":["stanowisko"]},{"key":"reklama","name":"Reklama na samochód","description":"Mobilna promocja Twojej marki. Płacisz za realnie wykorzystane materiały i roboczogodziny. Zwykle 2–4 godziny. Darmowa wycena.","category":"Grafika i reklama","price":0,"priceFrom":false,"durationMinutes":240,"resources":["stanowisko"]},{"key":"mycie","name":"Mycie detailingowe","description":"Kompleksowe mycie karoserii, kół i felg – przygotowanie do zabezpieczenia. Darmowa wycena.","category":"Detailing","price":0,"priceFrom":false,"durationMinutes":180,"resources":["stanowisko"]},{"key":"felgi","name":"Zabezpieczanie felg","description":"Ochrona felg przed pyłem z klocków i brudem. Darmowa wycena.","category":"Detailing","price":0,"priceFrom":false,"durationMinutes":120,"resources":["stanowisko"]},{"key":"szyby","name":"Przyciemnianie szyb","description":"Przyciemnianie szyb folią. Darmowa wycena.","category":"Detailing","price":0,"priceFrom":false,"durationMinutes":240,"resources":["stanowisko"]},{"key":"wnetrze","name":"Renowacja wnętrza – pranie tapicerki i impregnacja skór","description":"Odnowienie wnętrza pojazdu. Darmowa wycena.","category":"Detailing","price":0,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]}],"infoCards":[{"icon":"shield","title":"Gwarancja 10 lat na PPF","text":"Folia z TPU – samoregeneracja drobnych rys, 100% przezroczysta."},{"icon":"clock","title":"Zgodnie z terminem","text":"Każdy projekt doprowadzamy do końca w ustalonym czasie."},{"icon":"sparkle","title":"Darmowa wycena","text":"Dobierzemy zakres ochrony do potrzeb, budżetu i sposobu użytkowania auta."}],"gallery":[{"image":"/s/car-lab/media/work-gt4rs.webp","caption":"Porsche 718 Cayman GT4 RS Clubsport"},{"image":"/s/car-lab/media/work-cls.webp","caption":"Mercedes-Benz CLS"},{"image":"/s/car-lab/media/work-megane.webp","caption":"Renault Mégane R.S."},{"image":"/s/car-lab/media/work-z3.webp","caption":"BMW Z3"},{"image":"/s/car-lab/media/work-wrangler.webp","caption":"Jeep Wrangler"},{"image":"/s/car-lab/media/work-s3.webp","caption":"Audi S3"},{"image":"/s/car-lab/media/work-mx5.webp","caption":"Mazda MX-5"},{"image":"/s/car-lab/media/work-superb.webp","caption":"Škoda Superb"},{"image":"/s/car-lab/media/work-mercedes.webp","caption":"Mercedes-Benz"},{"image":"/s/car-lab/media/work-ppf.webp","caption":"Aplikacja folii ochronnej PPF"},{"image":"/s/car-lab/media/work-cls-wnetrze.webp","caption":"Wnętrze Mercedes-Benz"},{"image":"/s/car-lab/media/work-wrangler-wnetrze.webp","caption":"Wnętrze Jeep Wrangler"}],"faq":[{"question":"Ile kosztuje folia PPF?","answer":"Cena zależy od wielkości auta, skomplikowania nadwozia, pakietu (np. Full Front albo całe auto) i marki folii. Średnio od kilku tysięcy złotych za pakiet Front do kilkunastu tysięcy za całe nadwozie. Kolorowa folia PPF na całe auto to zwykle 11 000–19 000 zł netto.","keywords":["ppf","folia","full front","full body","kolorow"]},{"question":"Ile kosztuje powłoka ceramiczna?","answer":"Od 1800 zł brutto za powłokę roczną. Pakiet premium (lakier na 5 lat, felgi i szyby) od 3300 zł brutto. Do wyboru warianty na 1 rok, 3 lata lub 5 lat.","keywords":["ile kosztuje","koszt","ile trzyma","trwalos"]},{"question":"Kiedy powłoka ceramiczna nie ma sensu?","answer":"Gdy lakier jest w złym stanie i nie został przygotowany albo gdy auto ma być myte tylko na szczotkach. Jeśli zależy Ci na wysokiej odporności na uszkodzenia mechaniczne – lepsza będzie folia PPF.","keywords":["nie ma sensu","sensu","szczotk","kiedy nie","oplaca","ceramik"]},{"question":"Czy muszę okleić całe auto?","answer":"Nie – możesz zabezpieczyć tylko najbardziej narażone elementy albo zdecydować się na ochronę całego auta. Dobierzemy zakres do Twoich potrzeb i budżetu.","keywords":["cale auto","calego","wybrane","elementy","musze"]},{"question":"Gdzie was znajdę?","answer":"Katowice, ul. Kościuszki 257. Obsługujemy klientów z całego Śląska.","keywords":["gdzie","adres","kosciuszki","dojazd"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'b22892c5765e8515daedaa1e35fee7c69f06f87ca09ce12057b9a17e42f3d4e2', true);
