select public.svc_sync_tenant('{"slug":"carsfit","name":"CarsFIT Brno","shortName":"CarsFIT","kind":"detailing","tagline":"PPF fólie, keramická ochrana, polepy aut a detailing v centru Brna","description":"Favorit nebo Ferrari? U nás neděláme rozdíly – každé auto dostane maximální péči. Máme mnohaleté zkušenosti v detailingu a klademe důraz na kvalitu. Nabízíme důkladné čištění interiéru, renovace laku s ošetřením nejkvalitnějšími vosky a keramickými povlaky, PPF fólie i polepy. Po odvedené práci vám předáme naše zkušenosti a rady, jak se o auto starat.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#E3262E","contacts":{"phone":"+420604404051","address":"Špitálka 23a, 602 00 Brno-střed","legalAddress":"Carsfitdetailing s.r.o., IČO 21621683","mapUrl":"https://www.google.com/maps/search/?api=1&query=%C5%A0pit%C3%A1lka%2023a%2C%20602%2000%20Brno","email":"info@carsfit.cz"},"images":{"hero":"/s/carsfit/media/hero.webp","logo":"/s/carsfit/media/logo.png"},"hours":{"mon":[["08:00","17:00"]],"tue":[["08:00","17:00"]],"wed":[["08:00","17:00"]],"thu":[["08:00","17:00"]],"fri":[["08:00","17:00"]],"sat":[],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":240,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"box-1","name":"Garáž"}],"services":[{"key":"myti","name":"Detailingové ruční mytí","description":"Cca 2 hod. Ruční mytí, čištění disků, dekontaminace laku od polétavé rzi a asfaltu, keramický sealant, impregnace plastů a pneu.","category":"Základní služby","price":2000,"priceFrom":false,"durationMinutes":120,"resources":["box-1"]},{"key":"interier","name":"Čištění interiéru","description":"Cca 4 hod. Hloubkové vysátí a vyčištění celého vozu, tepování s