box-1"]},{"key":"zima","name":"Příprava vozu na sezonu s keramikou až na 3 roky","description":"Ruční mytí karoserie, dekontaminace laku, jednokrokové leštění, odmaštění a keramický povlak laku s životností až 3 roky – vše, co auto potřebuje před nadcházející sezonou.","category":"Leštění a keramika","price":14000,"priceFrom":false,"durationMinutes":2880,"resources":["box-1"]},{"key":"lesteni","name":"Jednokrokové leštění laku bez ochrany","description":"Odstranění cca 70 % vad laku a oživení vzhledu.","category":"Leštění a keramika","price":8000,"priceFrom":true,"durationMinutes":1440,"resources":["box-1"]},{"key":"nasiol-zr53","name":"Keramická ochrana laku NASIOL ZR53 (3 roky)","description":"Certifikovaná keramická ochrana laku: odolnost vůči soli a chemii, snazší údržba, lepší odvod vody a špíny, tvrdost 10H.","category":"Leštění a keramika","price":8000,"priceFrom":false,"durationMinutes":1440,"resources":["box-1"]},{"key":"nasiol-nl272","name":"Keramická ochrana laku NASIOL NL272 (5 let)","description":"Prémiová certifikovaná keramická ochrana laku s výjimečnými vlastnostmi a samohojivým efektem, tvrdost 10H.","category":"Leštění a keramika","price":16000,"priceFrom":false,"durationMinutes":1440,"resources":["box-1"]},{"key":"kola","name":"Keramická ochrana kol a třmenů na 2 roky","description":"Detailní mytí podběhů, kol a brzdových třmenů a keramická ochrana.","category":"Leštění a keramika","price":8000,"priceFrom":false,"durationMinutes":480,"resources":["box-1"]},{"key":"steraky","name":"Tekuté stěrače čelního okna včetně leštění","description":"Ošetření čelního skla včetně leštění. Všechna okna od 3 000 Kč.","category":"Leštění a keramika","price":1500,"priceFrom":false,"durationMinutes":60,"resources":["box-1"]},{"key":"ppf-front","name":"Full Front PPF fólií GSWF","description":"Polep přední části vozu ochrannou fólií: kapota, přední nárazník, světla, blatníky, A sloupky, pás na střeše, zrcátka. Záruka na fólii 10 let, fólie už má keramickou ochranu. Cena dle typu vozidla, doba cca 3 dny.","category":"Fólie a tónování","price":30000,"priceFrom":true,"durationMinutes":4320,"resources":["box-1"]},{"key":"ppf-svetla","name":"PPF předních světel","description":"Ochrana světel před poškozením, záruka 10 let na kvalitu fólie. Před aplikací doporučujeme leštění a broušení (+3 000 Kč).","category":"Fólie a tónování","price":2000,"priceFrom":false,"durationMinutes":120,"resources":["box-1"]},{"key":"ppf-hrana","name":"Polepení nákladové hrany kufru PPF fólií","description":"Ochrana nákladové hrany kufru proti oděrům.","category":"Fólie a tónování","price":2000,"priceFrom":false,"durationMinutes":60,"resources":["box-1"]},{"key":"tonovani-standart","name":"Tónování oken – Standart","description":"Osobní vůz: Coupe 3 500 Kč, Sedan 4 000 Kč, Kombi 4 500 Kč.","category":"Fólie a tónování","price":3500,"priceFrom":true,"durationMinutes":240,"resources":["box-1"]},{"key":"tonovani-premium","name":"Tónování oken – Premium","description":"Osobní vůz: Coupe 5 500 Kč, Sedan 6 000 Kč, Kombi 6 500 Kč.","category":"Fólie a tónování","price":5500,"priceFrom":true,"durationMinutes":240,"resources":["box-1"]},{"key":"zadni-svetla","name":"Zatmavení zadních světel fólií","description":"Podle velikosti a požadavků zákazníka.","category":"Fólie a tónování","price":2000,"priceFrom":true,"durationMinutes":120,"resources":["box-1"]},{"key":"dechrome","name":"Dechrome okrasných lišt fólií","description":"Podle velikosti a požadavků zákazníka.","category":"Fólie a tónování","price":4000,"priceFrom":true,"durationMinutes":480,"resources":["box-1"]},{"key":"svetla","name":"Leštění a broušení světel s keramikou na 2 roky","description":"Strojní broušení světel od zrnitosti 360 až po 3000, poté leštění do vysokého lesku a keramická ochrana na 2 roky.","category":"Další úpravy","price":2000,"priceFrom":true,"durationMinutes":180,"resources":["box-1"]},{"key":"volant","name":"Renovace volantu","description":"Důkladné čištění, kitování, broušení a barvení systémem Fenice – volant není třeba přešívat novou kůží.","category":"Další úpravy","price":3000,"priceFrom":true,"durationMinutes":480,"resources":["box-1"]},{"key":"trmeny","name":"Natírání brzdových třmenů barvou","description":"Obroušení třmenů a nátěr ve zvolené barvě ve 2 vrstvách.","category":"Další úpravy","price":4000,"priceFrom":true,"durationMinutes":480,"resources":["box-1"]}],"infoCards":[{"icon":"shield","title":"Certifikované středisko NASIOL","text":"Keramické povlaky s dlouhou životností a silnou chemickou odolností – na 3 nebo 5 let."},{"icon":"medal","title":"Certifikace Fenice","text":"Opravíme protrženou nebo propálenou kůži, ošoupané bočnice i volant."},{"icon":"car","title":"Osobní auta i tahače","text":"Ostrava, Poruba, Klimkovice, Bílovec, Studénka a okolí."}],"gallery":[{"image":"/s/db-autodetailing/media/work-audi.webp","caption":"Audi A6 allroad"},{"image":"/s/db-autodetailing/media/work-mercedes.webp","caption":"Mercedes-Benz GLE"},{"image":"/s/db-autodetailing/media/work-skoda.webp","caption":"Škoda Octavia"},{"image":"/s/db-autodetailing/media/work-kuze.webp","caption":"Čištění kůže – rozdíl je vidět hned"},{"image":"/s/db-autodetailing/media/work-motor.webp","caption":"Mytí motoru"},{"image":"/s/db-autodetailing/media/work-volant.webp","caption":"Renovace volantu systémem Fenice"},{"image":"/s/db-autodetailing/media/work-tesla-ppf.webp","caption":"PPF fólie na displej, Tesla"},{"image":"/s/db-autodetailing/media/work-svetla.webp","caption":"Broušení a leštění světlometů"},{"image":"/s/db-autodetailing/media/work-bmw-nasiol.webp","caption":"Keramická ochrana NASIOL ZR53, BMW"},{"image":"/s/db-autodetailing/media/work-tahac-nasiol.webp","caption":"Keramická ochrana NASIOL, tahač"},{"image":"/s/db-autodetailing/media/work-tahace.webp","caption":"Péče o nákladní tahače"},{"image":"/s/db-autodetailing/media/work-motocykl.webp","caption":"Čištění motocyklu"},{"image":"/s/db-autodetailing/media/work-bmw-interier.webp","caption":"Interiér po čištění, BMW"},{"image":"/s/db-autodetailing/media/work-pena.webp","caption":"Ruční mytí, BMW"}],"faq":[{"question":"Kolik to bude stát?","answer":"Všechna vozidla oceňuji individuálně a osobní konzultace ke každému vozidlu je ZDARMA. Ceny v ceníku jsou výchozí. U MPV, SUV a dodávek se cena navyšuje o 25 %.","keywords":["kolik to bude stat","kolik me to bude stat","individualn","konzultac","suv","mpv","dodavk","priplat"]},{"question":"Platí se záloha?","answer":"Při větších objednávkách je záloha 50 % z předpokládané ceny.","keywords":["zaloh","predem zaplatit","platba predem"]},{"question":"Kde vás najdu?","answer":"Záhumenní 2034/103, Ostrava-Poruba – budova B ze dvora. Působíme v okruhu Ostrava, Poruba, Polanka nad Odrou, Vřesina, Klimkovice, Zbyslavice, Josefovice, Jistebník, Olbramice, Bílovec, Bravantice, Studénka, Kyjovice, Horní a Dolní Lhota.","keywords":["kde vas najdu","najdu","adres","kde jste","budova","dvora","okoli","jezdite","pusobite"]},{"question":"Opravíte poškozenou kůži nebo ošoupaný volant?","answer":"Ano. Máme certifikaci RENOVACE KŮŽE V AUTOMOBILECH systémem Fenice. Opravíme poškozenou bočnici, protržený sedák, propálení nebo ošoupaný volant a doplněním barvy vrátíme původní vzhled. Volant není třeba přešívat novou kůží.","keywords":["oprav","protrz","propal","osoupan","bocnic","volant","fenice"]},{"question":"Kolik stojí tónování oken?","answer":"Standart: Coupe 3 500 Kč, Sedan 4 000 Kč, Kombi 4 500 Kč. Premium: Coupe 5 500 Kč, Sedan 6 000 Kč, Kombi 6 500 Kč.","keywords":["tonovan","tonovat","okna fol"]},{"question":"Nabízíte dárkové poukazy?","answer":"Ano, dárkový poukaz od 1 000 Kč je ideální dárek pro přátele nebo rodinu. Stačí zavolat nebo napsat.","keywords":["poukaz","darek","darkov","voucher"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'b8d0e60bedad2c78951b60a7a60d33a6ff126aa9a46f5238dc6598d1d0e82614', true);
