lia PPF CarbonQ – Full Front","description":"Zderzak przód, lampy przód, maska, błotniki przód, lusterka, słupki A, wnęki klamek i próg załadunkowy bagażnika. Cena netto.","category":"Folia PPF","price":5700,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ppf-full-body","name":"Folia PPF CarbonQ – Full Body","description":"Całe auto bezbarwną folią ochronną. Cena netto.","category":"Folia PPF","price":13500,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"ppf-lampy","name":"Folia PPF – lampy przód","description":"Ochrona przednich lamp. Cena netto.","category":"Folia PPF","price":600,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"ppf-prog","name":"Folia PPF – próg załadunkowy bagażnika","description":"Ochrona progu bagażnika. Cena netto.","category":"Folia PPF","price":350,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"ppf-progi","name":"Folia PPF – progi wewnętrzne","description":"Ochrona progów przy wsiadaniu. Cena netto.","category":"Folia PPF","price":550,"priceFrom":true,"durationMinutes":90,"resources":["stanowisko"]},{"key":"ppf-klamki","name":"Folia PPF – wnęki klamek (4 szt.)","description":"Ochrona wnęk klamek przed zarysowaniem. Cena netto.","category":"Folia PPF","price":350,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"ppf-ranty","name":"Folia PPF – ranty drzwi (4 szt.)","description":"Ochrona krawędzi drzwi. Cena netto.","category":"Folia PPF","price":250,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"kolor-zew","name":"Zmiana koloru – pakiet zewnętrzny (bez wnęk)","description":"Zmiana koloru nadwozia folią. Cena netto.","category":"Zmiana koloru i inne","price":9000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"kolor-wneki","name":"Zmiana koloru – pakiet zewnętrzny z wnękami","description":"Zmiana koloru nadwozia folią wraz z wnękami. Cena netto.","category":"Zmiana koloru i inne","price":15000,"priceFrom":true,"durationMinutes":10080,"resources":["stanowisko"]},{"key":"dechroming","name":"Dechroming i dekory wnętrza","description":"Zmiana koloru elementów chromowanych i dekorów wewnętrznych – wycena indywidualna.","category":"Zmiana koloru i inne","price":0,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]},{"key":"szyby","name":"Przyciemnianie szyb","description":"Przyciemnianie szyb w samochodzie. Cena netto.","category":"Zmiana koloru i inne","price":500,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"podwozie","name":"Konserwacja podwozia","description":"Zabezpieczenie antykorozyjne podwozia. Cena netto.","category":"Zmiana koloru i inne","price":2000,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"inspekcja","name":"Inspekcja nowego auta w salonie","description":"Sprawdzenie stanu lakieru i wnętrza nowego auta przed odbiorem. Cena netto.","category":"Zmiana koloru i inne","price":600,"priceFrom":false,"durationMinutes":120,"resources":["stanowisko"]}],"infoCards":[{"icon":"shield","title":"Folie PPF CarbonQ","text":"Bezbarwna folia ochronna – od wybranych elementów po całe auto."},{"icon":"sparkle","title":"Indywidualna wycena","text":"Każdy samochód wyceniamy także indywidualnie, według jego stanu."},{"icon":"car","title":"Inspekcja w salonie","text":"Sprawdzimy nowe auto, zanim je odbierzesz."}],"gallery":[{"image":"/s/detailking-krakow/media/work-rs6.webp","caption":"Audi RS6"},{"image":"/s/detailking-krakow/media/work-bmw8.webp","caption":"BMW serii 8 Gran Coupé"},{"image":"/s/detailking-krakow/media/work-cla45.webp","caption":"Mercedes-AMG CLA 45 S"},{"image":"/s/detailking-krakow/media/work-challenger.webp","caption":"Dodge Challenger"},{"image":"/s/detailking-krakow/media/work-mercedes.webp","caption":"Mercedes-Benz klasy S i GLE"},{"image":"/s/detailking-krakow/media/work-bmw7.webp","caption":"BMW serii 7"},{"image":"/s/detailking-krakow/media/work-e30.webp","caption":"BMW serii 3 E30 Touring"},{"image":"/s/detailking-krakow/media/work-m3.webp","caption":"BMW M3 E46"},{"image":"/s/detailking-krakow/media/work-bmw2.webp","caption":"BMW serii 2 Coupé"},{"image":"/s/detailking-krakow/media/work-jeep.webp","caption":"Jeep Grand Cherokee"},{"image":"/s/detailking-krakow/media/work-lexus.webp","caption":"Lexus UX"},{"image":"/s/detailking-krakow/media/work-ppf.webp","caption":"Aplikacja folii ochronnej PPF"},{"image":"/s/detailking-krakow/media/work-korekta.webp","caption":"Korekta lakieru"},{"image":"/s/detailking-krakow/media/work-podwozie.webp","caption":"Konserwacja podwozia"}],"faq":[{"question":"Czy ceny są netto?","answer":"Tak, ceny w cenniku są cenami netto. Każdy samochód wyceniamy również indywidualnie w zależności od jego stanu.","keywords":["netto","brutto","vat","faktur"]},{"question":"Czy powłokę ceramiczną można nałożyć bez korekty?","answer":"Nie – do każdej powłoki ceramicznej wymagana jest co najmniej jednoetapowa korekta lakieru (od 950 zł netto).","keywords":["bez korekty","wymagan","przed powlok","ceramik"]},{"question":"Co obejmuje Full Front?","answer":"Zderzak przód, lampy przód, maskę, błotniki przód, lusterka, słupki A, wnęki klamek i próg załadunkowy bagażnika – folią PPF CarbonQ, od 5700 zł netto.","keywords":["full front","obejmuje","zawiera","co wchodzi"]},{"question":"Gdzie was znajdę?","answer":"Kraków, ul. Longinusa Podbipięty 77. Zadzwoń: 501 031 414.","keywords":["gdzie","adres","podbipiet","dojazd","dojechac"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'c57c53d3339ebf9c329c06c0be7fb087c893672087cce3095b1ab0598330bbbd', true);
