select public.svc_sync_tenant('{"slug":"jh-auto-detailing","name":"JH Auto Detailing","shortName":"JH Detailing","kind":"detailing","tagline":"Čištění interiéru, leštění laku, keramika, PPF a tónování oken v Tišnově","description":"Jsme detailingové studio v Tišnově. Postaráme se o interiér od základního vysátí až po tepování sedaček, vyleštíme lak a ochráníme ho voskem nebo keramikou. Lepíme PPF fólie a tónujeme okna s atestem. Termín si zarezervujete online během minuty – bez registrace.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#E1251B","contacts":{"phone":"+420777056596","address":"Olbrachtova 1740, 666 03 Tišnov","legalAddress":"Květnická 1621, 666 01 Tišnov","mapUrl":"https://www.google.com/maps/search/?api=1&query=Olbrachtova%201740%2C%20666%2003%20Ti%C5%A1nov","whatsapp":"+420777056596","instagram":"jh_auto_detailing","facebook":"jhautodetailingcz","email":"info@detailni-cisteni.cz"},"images":{"hero":"/s/jh-auto-detailing/media/hero-2.webp","logo":"/s/jh-auto-detailing/media/logo.png"},"hours":{"mon":[["08:00","17:00"]],"tue":[["08:00","17:00"]],"wed":[["08:00","17:00"]],"thu":[["08:00","17:00"]],"fri":[["08:00","17:00"]],"sat":[],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":120,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"box-1","name":"Box 1"}],"services":[{"key":"interier-1","name":"Interiér 1: Základní čištění","description":"Vysátí interiéru a kufru, utření prachu, provonění.","category":"Interiér","price":1600,"priceFrom":true,"durationMinutes":240,"resources":["box-1"]},{"key":"interier-2","name":"Interiér 2: Detailní údržba","description":"Vše ze základního čištění a navíc komplexní čištění, okna zevnitř, čištění mezidveřních prostor a impregnace plastů.","category":"Interiér","price":2700,"priceFrom":true,"durationMinutes":480,"resources":["box-1"]},{"key":"interier-3","name":"Interiér 3: Čištění a tepování","description":"Vše z detailní údržby a navíc tepování sedaček a tepování kufru.","category":"Interiér","price":3600,"priceFrom":true,"durationMinutes":2880,"resources":["box-1"]},{"key":"lesteni-bronz","name":"Leštění laku Bronz","description":"Vydrží týdny. Detailní mytí a dekontaminace laku, jednostupňové leštění (odstraní 60–70 % škrábanců), ochrana detailerem na 4–8 týdnů.","category":"Leštění laku","price":7000,"priceFrom":true,"durationMinutes":4320,"resources":["box-1"]},{"key":"lesteni-silver","name":"Leštění laku Silver","description":"Vydrží měsíce. Detailní mytí a dekontaminace laku, dvoustupňové leštění (70–80 % škrábanců), ochrana syntetickým voskem na 6 měsíců, leštění světlometů, impregnace pneumatik a plastů.","category":"Leštění laku","price":10000,"priceFrom":true,"durationMinutes":10080,"resources":["box-1"]},{"key":"lesteni-gold","name":"Leštění laku Gold","description":"Vydrží až 5 let. Detailní mytí a dekontaminace laku, dvou- až třístupňové leštění (80–95 % škrábanců), keramická ochrana až na 5 let, leštění světlometů, impregnace pneumatik a plastů.","category":"Leštění laku","price":12000,"priceFrom":true,"durationMinutes":10080,"resources":["box-1"]},{"key":"ochrana-detailer","name":"Detailer: rychlé osvěžení laku","description":"Rychlé osvěžení vzhledu laku a ochrana na týdny.","category":"Ochrana laku","price":3000,"priceFrom":true,"durationMinutes":180,"resources":["box-1"]},{"key":"ochrana-vosk","name":"Syntetický vosk","description":"Lesk a ochrana laku na měsíce.","category":"Ochrana laku","price":4000,"priceFrom":true,"durationMinutes":240,"resources":["box-1"]},{"key":"ochrana-keramika","name":"Keramická ochrana laku","description":"Keramický povlak, který vydrží až 5 let. Varianty na 1, 3 nebo 5 let.","category":"Ochrana laku","price":5000,"priceFrom":true,"durationMinutes":1440,"resources":["box-1"]},{"key":"ppf-dily","name":"PPF fólie na díly vozu","description":"Ochrana jednotlivých dílů vozu: přední světla, sloupky dveří, zpětná zrcátka, misky pod kliky a další díly dle domluvy.","category":"PPF fólie","price":2000,"priceFrom":true,"durationMinutes":240,"resources":["box-1"]},{"key":"svetla-renovace","name":"Renovace světlometů","description":"Renovace a rozleštění zašlých světlometů.","category":"Světlomety","price":1600,"priceFrom":true,"durationMinutes":120,"resources":["box-1"]},{"key":"svetla-keramika","name":"Keramická ochrana světlometů","description":"Tenký a tvrdý keramický povlak. Chrání před škrábanci, UV zářením a chemií. Životnost 1–2 roky.","category":"Světlomety","price":800,"priceFrom":false,"durationMinutes":60,"resources":["box-1"]},{"key":"svetla-ppf","name":"PPF fólie na světlomety","description":"Ochrana proti kamínkům a mechanickému poškození. Životnost až 5–7 let.","category":"Světlomety","price":2000,"priceFrom":true,"durationMinutes":120,"resources":["box-1"]},{"key":"tonovani-predni","name":"Tónování předních bočních oken","description":"Tónování s atestem a kartičkou o aplikaci. Fólie KeetecFol Protector a Infrasol, zatmavení max. 30 % – legálně na STK.","category":"Tónování oken","price":1600,"priceFrom":true,"durationMinutes":1440,"resources":["box-1"]},{"key":"tonovani-zadni","name":"Tónování zadních oken","description":"Tónování s atestem a kartičkou o aplikaci. Fólie KeetecFol Protector a Infrasol s propustností 5 %, 25 % nebo 45 % (zatmavení 95 %, 75 % nebo 55 %).","category":"Tónování oken","price":3000,"priceFrom":true,"durationMinutes":2880,"resources":["box-1"]},{"key":"sunstrip","name":"Sunstrip","description":"Protisluneční pruh s atestem a kartičkou o aplikaci, fólie Infrasol.","category":"Tónování oken","price":800,"priceFrom":true,"durationMinutes":480,"resources":["box-1"]}],"infoCards":[{"icon":"sparkle","title":"Interiér jako nový","text":"Tepování sedaček, impregnace plastů a čištění i mezidveřních prostor."},{"icon":"shield","title":"Fólie s atestem","text":"Tónování oken s atestem a kartičkou o aplikaci – legálně na STK."},{"icon":"clock","title":"Rezervace online","text":"Termín si vyberete sami, bez registrace a bez čekání na telefonu."}],"gallery":[{"image":"/s/jh-auto-detailing/media/work-g1-after.webp","before":"/s/jh-auto-detailing/media/work-g1-before.webp","caption":"Kompletní čištění interiéru, Ford Focus"},{"image":"/s/jh-auto-detailing/media/work-dacia-duster-after.webp","before":"/s/jh-auto-detailing/media/work-dacia-duster-before.webp","caption":"Čištění interiéru, Dacia Duster"},{"image":"/s/jh-auto-detailing/media/work-g7-after.webp","before":"/s/jh-auto-detailing/media/work-g7-before.webp","caption":"Tepování koberců, Porsche Cayenne GTS"},{"image":"/s/jh-auto-detailing/media/work-g8-after.webp","before":"/s/jh-auto-detailing/media/work-g8-before.webp","caption":"Tepování kufru"},{"image":"/s/jh-auto-detailing/media/work-g2-after.webp","before":"/s/jh-auto-detailing/media/work-g2-before.webp","caption":"Čištění sedaček a interiéru"},{"image":"/s/jh-auto-detailing/media/work-g9-after.webp","before":"/s/jh-auto-detailing/media/work-g9-before.webp","caption":"Čištění výplně dveří"},{"image":"/s/jh-auto-detailing/media/work-porsche-interior.webp","caption":"Interiér po čištění, Porsche"}],"faq":[{"question":"Jak dlouho budu bez vozu?","answer":"Doba realizace závisí na zvolené službě, rozsahu práce a stavu vozu. Vždy předem sdělím předpokládaný termín předání zpět do Vašich rukou.\n\nZákladní údržba interiéru: 3–4 hodiny.\nČištění interiéru suchou cestou: během 1 dne.\nTepování a čištění kůže: do 2 dnů.\nTónování oken: do 2 dnů.\nJednokrokové leštění laku: 3–5 dnů.\nDvou- a vícekrokové leštění laku: 7–10 dnů.","keywords":["jak dlouho","dlouho","bez vozu","bez auta","doba realizace","trva","trvat","kdy bude hotov","za jak dlouho"]},{"question":"Kolik mě to bude stát?","answer":"Ceny uvedené v ceníku jsou orientační a představují základní cenu jednotlivých služeb. Konečná cena se následně odvíjí od konkrétního vozu, jeho velikosti, aktuálního stavu a rozsahu domluvené služby.\n\nU SUV a vícemístných vozů (více než 5 míst) platí příplatek 20 %. Při silném znečištění vozu se příplatek pohybuje od 20 %.\n\nNejlepší je nejprve se domluvit telefonicky, zprávou nebo osobně přímo s vozem přijet ke mně. Díky tomu můžu posoudit jeho stav a upřesnit orientační cenu.","keywords":["kolik me to bude stat","kolik to bude stat","konecna cena","priplat","suv","vicemistn","sedmimist","orientacni","velke auto","velky vuz"]},{"question":"Vyzvednete si vůz u mě?","answer":"Ano. Po předchozí domluvě si vůz mohu vyzvednout přímo u vás. V rámci Tišnova je vyzvednutí zdarma, do 30 km od Tišnova od 200 Kč. Po dokončení Vám vůz po domluvě opět přivezu zpět.","keywords":["vyzvednete","vyzvednout","vyzvedne","odvoz","odvezete","privezete","pristaveni","prijedete pro","u me doma","dovoz","dovezete"]},{"question":"Jak často má smysl detailní čištění?","answer":"U běžně používaného vozu doporučuji detailní čištění přibližně 1–2× ročně. Ideální je péči přizpůsobit tomu, jak a jak často vůz používáte. Po zimě a před nebo po letní dovolené je vhodný čas na důkladnější vyčištění a ošetření interiéru. Pokud ve voze vozíte děti nebo domácí mazlíčky, vyplatí se důkladné tepování zařadit častěji.\n\nKeramickou ochranu není potřeba obnovovat každý rok. Její životnost závisí na konkrétním typu ochrany a následné péči, zpravidla 1, 3 nebo 5 let. Pro zachování jejích vlastností je ale důležité keramiku průběžně vyživovat a správně udržovat.","keywords":["jak casto","kolikrat","jednou za","pravidelne","obnovovat","zivotnost","vydrzi keramika","kazdy rok"]},{"question":"Co když je vůz opravdu hodně špinavý?","answer":"Není problém. Postarám se i o vozy, které delší dobu nebyly důkladně čištěné nebo jsou ve výrazně horším stavu. U silného znečištění se účtuje příplatek od 20 %, vždy podle skutečného stavu a náročnosti práce.","keywords":["spinav","znecist","spina","chlupy","zvirat","mazlic","horsim stavu"]},{"question":"Jak se platí?","answer":"Platbu je možné provést hotově nebo bankovním převodem při předání vozu. Pro pohodlnou úhradu převodem je na faktuře k dispozici také QR platba. Platební karty ani CCS karty nepřijímám. Pokud budete chtít vystavit fakturu na své jméno, není problém – fakturu vystavím i soukromým osobám.","keywords":["plati","platit","platba","zaplatit","kartou","karty","hotove","hotovost","prevodem","faktur","qr","ccs"]},{"question":"Jak se ke mně dostanete?","answer":"Najdete mě na adrese Olbrachtova 1740. SPRÁVNÝ VJEZD JE PŘES STAVEBNINY TRIMOT / CIMTO – brána je hned u silnice. Nevjíždějte do areálu SINCLAIR. Pro snadnou orientaci najdete dole na stránce také mapu s přesným umístěním.","keywords":["dostanu","dostat","dostanete","vjezd","kde vas najdu","najdu","kde jste","adresa","adresu","cesta","parkov","brana","trimot","cimto","sinclair","navigace"]}],"owner":{"email":"alqezas@gmail.com"},"assistant":{"enabled":true}}'::jsonb, '94ce8fe817876c49953987ba465af92240dab6965562766099a6544dabe08b75', true);
