n":"Dla bardzo zniszczonych lakierów – usuwa do 99% zarysowań. Cena 3999–4999 zł.","category":"Powłoki i korekta","price":3999,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"serwis-ceramiki","name":"Serwis powłoki ceramicznej","description":"Serwis powłok ceramicznych, kwarcowych i elastomerowych. Opcjonalnie usuwanie smoły i deironizacja – po 99 zł.","category":"Powłoki i korekta","price":499,"priceFrom":false,"durationMinutes":180,"resources":["stanowisko"]},{"key":"ppf-podstawowy","name":"Folia PPF – pakiet podstawowy","description":"Maska, zderzak przedni, lampy, błotniki, lusterka, słupki A i B, czołowa część dachu. Ok. 2 dni. Gwarancja do 10 lat, auto zastępcze MINI ONE gratis.","category":"Folia PPF i szyby","price":5000,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ppf-calosc","name":"Folia PPF – całe auto","description":"Wszystkie lakierowane elementy karoserii. Ok. 5 dni. Auto zastępcze MINI ONE gratis.","category":"Folia PPF i szyby","price":14000,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"ppf-lampy","name":"Folia PPF na lampy (2 szt.)","description":"Zabezpieczenie 2 przednich lamp folią PPF 190 mikronów.","category":"Folia PPF i szyby","price":400,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"przyciemnianie","name":"Przyciemnianie szyb","description":"Folie ceramiczne z odbijaniem UV i gwarancją trwałości kleju. 3 szyby 699 zł, 5 szyb 799 zł, 7 szyb 899 zł; busy – wycena indywidualna.","category":"Folia PPF i szyby","price":699,"priceFrom":true,"durationMinutes":360,"resources":["stanowisko"]},{"key":"mini","name":"Pranie tapicerki – Pakiet Mini","description":"Odkurzanie całego wnętrza z bagażnikiem, pranie tapicerki siedzeń, czyszczenie i impregnacja plastików, mycie szyb od środka, czyszczenie dywaników, impregnacja uszczelek, ozonowanie. Dotyczy też tapicerki skórzanej (czyszczenie skór). SUV/VAN +99–199 zł.","category":"Wnętrze","price":799,"priceFrom":false,"durationMinutes":360,"resources":["stanowisko"]},{"key":"podstawowy","name":"Pranie tapicerki – Pakiet Podstawowy","description":"Pakiet Mini oraz ręczne czyszczenie podsufitki i wnęk drzwiowych. SUV/VAN +99–199 zł.","category":"Wnętrze","price":999,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]},{"key":"rozszerzony","name":"Pranie tapicerki – Pakiet Rozszerzony","description":"Pakiet Podstawowy oraz pranie wykładziny podłogowej i demontaż foteli przednich w razie potrzeby. Pakiet PREMIUM z demontażem plastików i dekorów +499 zł.","category":"Wnętrze","price":1199,"priceFrom":false,"durationMinutes":600,"resources":["stanowisko"]},{"key":"skora-ceramika","name":"Powłoka ceramiczna na skóry (2 lata)","description":"Zabezpieczenie skórzanej tapicerki. Powłoka hydrofobowa 1-letnia – 600 zł.","category":"Wnętrze","price":1000,"priceFrom":false,"durationMinutes":180,"resources":["stanowisko"]},{"key":"materialy-hydrofob","name":"Powłoka hydrofobowa na siedzenia materiałowe (2 lata)","description":"Zabezpieczenie siedzeń materiałowych. Wersja 1-letnia – 500 zł.","category":"Wnętrze","price":800,"priceFrom":false,"durationMinutes":180,"resources":["stanowisko"]},{"key":"mycie","name":"Mycie detailingowe","description":"Cena zależna od wielkości i zabrudzenia auta. Przy korekcie lakieru – gratis. Glinkowanie i deironizacja – po 99 zł.","category":"Ochrona i pakiety","price":199,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"podwozie","name":"Konserwacja podwozia Waxoyl – nowe auto","description":"Cena promocyjna do 31.12.2026 (standardowo 4499 zł) dla aut do roku i ok. 10 tys. km. Gratis folia PPF na wnęki drzwi i powłoka hydrofobowa na szyby.","category":"Ochrona i pakiety","price":3499,"priceFrom":false,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"slub","name":"Przygotowanie auta do ślubu","description":"Mycie, odtłuszczenie lakieru, powłoka hydrofobowa na szyby i lakier + płynne szkło, montaż tablic i ozdób ślubnych. Gratis niespodzianka dla Państwa Młodych.","category":"Ochrona i pakiety","price":1399,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]},{"key":"weryfikacja","name":"Weryfikacja lakieru przed zakupem","description":"Pomiar grubości lakieru z raportem i zdjęciami w 20–30 minut. W studiu 0 zł, z dojazdem na terenie Białegostoku 150 zł.","category":"Ochrona i pakiety","price":0,"priceFrom":false,"durationMinutes":30,"resources":["stanowisko"]},{"key":"wygluszenie","name":"Wygłuszanie wnętrza","description":"Drzwi 599–899 zł/szt., nadkole 599–899 zł/szt., podłoga 1499–1999 zł, maska 599–799 zł, klapa bagażnika 599 zł. Dokładna wycena po obejrzeniu auta.","category":"Ochrona i pakiety","price":599,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]}],"infoCards":[{"icon":"medal","title":"Auto Detailing Roku","text":"W woj. podlaskim w latach 2022, 2024, 2025 i 2026 – plebiscyt Mistrzowie Motoryzacji ORLEN OIL."},{"icon":"shield","title":"Jedyni na Podlasiu","text":"Akredytacja powłok DELIXIRUM i elastomerów Titan Coatings."},{"icon":"car","title":"Door to door gratis","text":"Odbiór auta na terenie Białegostoku +10 km bezpłatnie, także z salonu."}],"gallery":[{"image":"/s/luxcar-bialystok/media/work-a6.webp","caption":"Audi A6"},{"image":"/s/luxcar-bialystok/media/work-astra-vxr.webp","caption":"Vauxhall Astra VXR – powłoka Delixirum Gold"},{"image":"/s/luxcar-bialystok/media/work-bmw6.webp","caption":"BMW serii 6"},{"image":"/s/luxcar-bialystok/media/work-cx5.webp","caption":"Mazda CX-5"},{"image":"/s/luxcar-bialystok/media/work-stonic.webp","caption":"Kia Stonic"},{"image":"/s/luxcar-bialystok/media/work-rav4.webp","caption":"Toyota RAV4"},{"image":"/s/luxcar-bialystok/media/work-ceed.webp","caption":"Kia Ceed"},{"image":"/s/luxcar-bialystok/media/work-bmw6-gc.webp","caption":"BMW serii 6 Gran Coupé"},{"image":"/s/luxcar-bialystok/media/work-superb.webp","caption":"Škoda Superb"},{"image":"/s/luxcar-bialystok/media/work-corolla.webp","caption":"Toyota Corolla"},{"image":"/s/luxcar-bialystok/media/work-civic.webp","caption":"Honda Civic – połysk po korekcie"},{"image":"/s/luxcar-bialystok/media/work-nagroda.webp","caption":"Auto Detailing Roku – Plebiscyt Mistrzowie Motoryzacji"}],"faq":[{"question":"Czy odbieracie auto?","answer":"Tak – door to door na terenie Białegostoku +10 km bezpłatnie (powyżej 20 km od siedziby płatne). Odbieramy też auto z salonu i sprawdzamy stan oraz grubość lakieru.","keywords":["odbier","door","dowoz","salon","odbior"]},{"question":"Czym różni się powłoka elastomerowa od ceramicznej?","answer":"Powłoka elastomerowa jest dużo bardziej wytrzymała, pochłania uderzenia i sama regeneruje rysy pod wpływem temperatury. Ceramika wymaga regularnego serwisu co pół roku lub rok (ok. 400–500 zł).","keywords":["elastomer","roznic","ceramik","titan"]},{"question":"Ile trwa wycena?","answer":"Bezpłatna wycena auta zajmuje 15 minut. Auta wyceniamy po oględzinach – przed przyjazdem prosimy dokładnie umyć auto.","keywords":["wycen","ogledzin","ile trwa","bezplat"]},{"question":"Czy dostanę auto zastępcze?","answer":"Tak, przy oklejaniu folią PPF i przyciemnianiu szyb odbierzesz bezpłatnie samochód zastępczy MINI ONE na czas usługi.","keywords":["zastepcz","mini one","samochod zastep"]},{"question":"Kiedy można dzwonić?","answer":"Zadzwoń codziennie 8–22: +48 722 143 568. Studio: ul. Techniczna 8/2, Białystok.","keywords":["dzwonic","telefon","kiedy","godzin","gdzie","adres","techniczn"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '533ed233a2e7887f4e8c6f723be1cb881a5b283d9849efd57d1c2686225cf4d9', true);
