select public.svc_sync_tenant('{"slug":"lv-detailing","name":"LV! Detailing Studio","shortName":"LV! Detailing","kind":"detailing","tagline":"Auto jako ze showroomu – detailing, PPF fólie a tónování skel v Ostravě","description":"Ať už máte novinku z autosalonu, nebo věrného parťáka po tisících kilometrech, u nás získá královský vzhled i ochranu. Specializujeme se na profesionální detailing, PPF fólie a tónování autoskel. Preciznost, top materiály a posedlost detailem – to je naše záruka. Každé auto bereme jako vlastní, ať má emblém Ferrari nebo Fabie.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#D4A63A","contacts":{"phone":"+420602336063","address":"Novinářská 1113/3, 709 00 Ostrava (Futurum)","legalAddress":"LV! Detailing Studio, IČO 23620731","mapUrl":"https://maps.app.goo.gl/q1Y5RvS5rdoFvpXMA","instagram":"lv_detailing_studio_futurum","facebook":"https://www.facebook.com/profile.php?id=61583990288755","email":"info@lvdetailing.cz"},"images":{"hero":"/s/lv-detailing/media/hero.webp","logo":"/s/lv-detailing/media/logo.png"},"hours":{"mon":[["08:00","17:00"]],"tue":[["08:00","17:00"]],"wed":[["08:00","17:00"]],"thu":[["08:00","17:00"]],"fri":[["08:00","17:00"]],"sat":[],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":240,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":15},"resources":[{"key":"box-1","name":"Box 1"},{"key":"box-2","name":"Box 2"}],"services":[{"key":"myti-zaklad","name":"Ruční mytí ZÁKLAD","description":"Předmytí, mytí NANO šamponem, mytí kol a podběhů, mytí a impregnace pneumatik, vysušení vozu.","category":"Mytí a čištění","price":599,"priceFrom":true,"durationMinutes":45,"resources":["box-1","box-2"]},{"key":"myti-exclusive","name":"Ruční mytí