olie i wrapping","price":1000,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"przyciemnianie","name":"Przyciemnianie szyb","description":"Przyciemnianie szyb folią.","category":"Folie i wrapping","price":500,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"quick","name":"Quick detailing wnętrza","description":"Odkurzanie podłogi, bagażnika i foteli, czyszczenie wszystkich plastików.","category":"Wnętrze i skóra","price":120,"priceFrom":false,"durationMinutes":60,"resources":["stanowisko"]},{"key":"wnetrze","name":"Detailing wnętrza","description":"Pranie kompletu foteli lub czyszczenie i impregnacja skóry, pranie dywaników, szczotkowanie, odkurzanie podłogi i bagażnika, czyszczenie i konserwacja plastików.","category":"Wnętrze i skóra","price":550,"priceFrom":true,"durationMinutes":300,"resources":["stanowisko"]},{"key":"wnetrze-pelne","name":"Pełny detailing wnętrza","description":"Z demontażem foteli: pranie foteli lub skóra, dywaniki, podłoga, bagażnik, podsufitka i wszystkie plastiki.","category":"Wnętrze i skóra","price":900,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"fotel","name":"Renowacja całego fotela","description":"Renowacja skóry fotela.","category":"Wnętrze i skóra","price":450,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"kierownica","name":"Renowacja kierownicy","description":"Renowacja skórzanej kierownicy.","category":"Wnętrze i skóra","price":250,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"zaprawki","name":"Zaprawki lakiernicze","description":"Punktowe zaprawki odprysków.","category":"Inne","price":70,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"wgniecenia","name":"Usuwanie wgnieceń","description":"Usuwanie wgnieceń bez lakierowania.","category":"Inne","price":80,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]},{"key":"rower","name":"Zabezpieczenie roweru","description":"Aplikacja folii zabezpieczającej i powłoki ceramicznej.","category":"Inne","price":1000,"priceFrom":false,"durationMinutes":240,"resources":["stanowisko"]},{"key":"motocykl","name":"Detailing motocykla","description":"Mycie detailingowe, polerowanie lakieru i chromów, zestaw powłok ceramicznych.","category":"Inne","price":1200,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]},{"key":"sprzedaz","name":"Przygotowanie auta do sprzedaży","description":"Detailing samochodu z myślą o korzystnej sprzedaży – wycena indywidualna.","category":"Inne","price":0,"priceFrom":false,"durationMinutes":480,"resources":["stanowisko"]}],"infoCards":[{"icon":"sparkle","title":"Perfekcja w każdym detalu","text":"Luksusowa pielęgnacja i najlepsze produkty."},{"icon":"credit-card","title":"Adekwatne ceny","text":"Profesjonalne usługi w dobrych cenach – przejrzysty cennik."},{"icon":"car","title":"Współpraca B2B","text":"Salony i komisy: door to door lub z dojazdem do Klienta."}],"gallery":[{"image":"/s/misc-detailing/media/work-corvette.webp","caption":"Chevrolet Corvette C8"},{"image":"/s/misc-detailing/media/work-cla45.webp","caption":"Mercedes-AMG CLA 45 S"},{"image":"/s/misc-detailing/media/work-mercedes-fiolet.webp","caption":"Mercedes-Benz"},{"image":"/s/misc-detailing/media/work-cla.webp","caption":"Mercedes-AMG CLA"},{"image":"/s/misc-detailing/media/work-bmw-m-zielone.webp","caption":"BMW M"},{"image":"/s/misc-detailing/media/work-bmw-m-niebieskie.webp","caption":"BMW M"},{"image":"/s/misc-detailing/media/work-defender.webp","caption":"Land Rover Defender"},{"image":"/s/misc-detailing/media/work-911.webp","caption":"Porsche 911"},{"image":"/s/misc-detailing/media/work-911-wnetrze.webp","caption":"Wnętrze Porsche 911"},{"image":"/s/misc-detailing/media/work-stinger.webp","caption":"Kia Stinger"},{"image":"/s/misc-detailing/media/work-bmw7.webp","caption":"BMW serii 7"},{"image":"/s/misc-detailing/media/work-bmw1.webp","caption":"BMW serii 1"},{"image":"/s/misc-detailing/media/work-gr-yaris.webp","caption":"Toyota GR Yaris"},{"image":"/s/misc-detailing/media/work-moto.webp","caption":"Detailing motocykla Yamaha Ténéré"}],"faq":[{"question":"Od czego zależy cena?","answer":"Polerowanie, zabezpieczenie lakieru i pakiet ceramiczny mają trzy ceny – dla małego, średniego i dużego samochodu. Folie i wrapping zależą od producenta folii i wielkości auta.","keywords":["od czego","zalezy","maly","sredni","duzy","wielkos"]},{"question":"Co zawiera pakiet powłok ceramicznych?","answer":"Powłokę karoserii o trwałości 5 lat, powłokę na szyby i felgi na 3 lata, powłokę na plastiki strukturalne do 2 lat oraz jednoetapowe polerowanie lakieru. Cena 3100–3500 zł.","keywords":["pakiet","ceramicz","zawiera","powlok"]},{"question":"Współpracujecie z salonami i komisami?","answer":"Tak – pracujemy z salonami i komisami samochodowymi w systemie door to door lub z dojazdem do Klienta.","keywords":["salon","komis","b2b","door","firm"]},{"question":"Robicie też motocykle i rowery?","answer":"Tak – detailing motocykla z powłokami ceramicznymi za 1200 zł i zabezpieczenie roweru folią i ceramiką za 1000 zł.","keywords":["motocykl","rower","motor"]},{"question":"Gdzie was znajdę?","answer":"Warszawa-Ursus, Aleje Jerozolimskie 236. Otwarte pon.–pt. 9:00–18:00, sobota 9:00–15:00.","keywords":["gdzie","adres","jerozolimsk","ursus","otwart","godzin","sobot"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'b52e270efe2094120b4976bdd8fb955b8b230458ea03680e4757c1187f546942', true);
