select public.svc_sync_tenant('{"slug":"olomouc-detailing","name":"Olomouc Detailing","shortName":"Olomouc Det.","kind":"detailing","tagline":"Čištění a péče o interiér aut v Olomouci","description":"Vracíme interiéru vašeho vozu čistotu, svěžest a vzhled nového auta. Precizní ruční práce s důrazem na detail. Šetříme váš čas – auto si po dohodě vyzvedneme u vás doma nebo v práci a vrátíme vám ho dokonale čisté.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#3B5BA9","contacts":{"phone":"+420797859558","address":"Olomouc a okolí (pick-up & delivery)","mapUrl":"https://www.google.com/maps/search/?api=1&query=Olomouc","instagram":"olomoucdetailing","facebook":"olomoucdetailing","tiktok":"olomoucdetailing"},"images":{"hero":"/s/olomouc-detailing/media/hero.webp","logo":"/s/olomouc-detailing/media/logo.png"},"hours":{"mon":[["08:00","18:00"]],"tue":[["08:00","18:00"]],"wed":[["08:00","18:00"]],"thu":[["08:00","18:00"]],"fri":[["08:00","18:00"]],"sat":[["08:00","18:00"]],"sun":[]},"closedDates":[],"booking":{"slotStepMinutes":60,"minLeadMinutes":1440,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":60},"resources":[{"key":"dilna","name":"Dílna"}],"services":[{"key":"male","name":"Kompletní čištění interiéru – malé vozy","description":"Fabia, Yaris, Golf… Hloubkové tepování sedadel, koberců, čalounění a kufru; detailní čištění, dezinfekce a impregnace plastů; čištění, výživa a impregnace kůže; mezidveřní prostory, prahy a okna z obou stran. Doba cca 8–12 hodin včetně sušení.","category":"Čištění interiéru","price":2500,"priceFrom":false,"durationMinutes":600,"resources":["dilna"]},{"key":"stredni","name":"Kompletní čištění interiéru – střední a velké vozy","description":"Octavia, Passat… Hloubkové tepování sedadel, koberců, čalounění a kufru; detailní čištění, dezinfekce a impregnace plastů; čištění, výživa a impregnace kůže; mezidveřní prostory, prahy a okna z obou stran. Doba cca 8–12 hodin včetně sušení.","category":"Čištění interiéru","price":3500,"priceFrom":false,"durationMinutes":600,"resources":["dilna"]},{"key":"suv","name":"Kompletní čištění interiéru – SUV / crossover / MPV","description":"Kodiaq, CX-5… Hloubkové tepování sedadel, koberců, čalounění a kufru; detailní čištění, dezinfekce a impregnace plastů; čištění, výživa a impregnace kůže; mezidveřní prostory, prahy a okna z obou stran. Doba cca 8–12 hodin včetně sušení.","category":"Čištění interiéru","price":4500,"priceFrom":false,"durationMinutes":1440,"resources":["dilna"]},{"key":"dodavka","name":"Kompletní čištění interiéru – dodávky a mikrobusy","description":"Hloubkové tepování sedadel, koberců, čalounění a kufru; detailní čištění, dezinfekce a impregnace plastů; čištění, výživa a impregnace kůže; mezidveřní prostory, prahy a okna z obou stran. Doba cca 8–12 hodin včetně sušení.","category":"Čištění interiéru","price":5000,"priceFrom":true,"durationMinutes":1440,"resources":["dilna"]},{"key":"ozon","name":"Dezinfekce klimatizace a ozonování interiéru","description":"Doplňková služba k čištění interiéru.","category":"Čištění interiéru","price":500,"priceFrom":false,"durationMinutes":60,"resources":["dilna"]}],"infoCards":[{"icon":"car","title":"Pick-up & Delivery","text":"Auto si po dohodě vyzvedneme u vás doma nebo v práci v Olomouci a okolí a vrátíme ho čisté."},{"icon":"sparkle","title":"Ruční práce","text":"Precizní ruční práce s důrazem na každý detail interiéru."},{"icon":"credit-card","title":"Jasný ceník","text":"Cena podle velikosti vozu – od 2 500 Kč za malé auto."}],"gallery":[{"image":"/s/olomouc-detailing/media/work-tepovani.webp","caption":"Hloubkové tepování sedadel"},{"image":"/s/olomouc-detailing/media/work-plasty.webp","caption":"Detailní čištění plastů štětci"}],"faq":[{"question":"Kolik stojí čištění interiéru?","answer":"Malé vozy (Fabia, Yaris, Golf) 2 500 Kč, střední a velké (Octavia, Passat) 3 500 Kč, SUV / crossover / MPV 4 500 Kč, dodávky a mikrobusy od 5 000 Kč. Dezinfekce klimatizace a ozonování +500 Kč.","keywords":["kolik","cena","cenik","stoji","suv","dodavk"]},{"question":"Jak dlouho čištění trvá?","answer":"Zhruba 8–12 hodin včetně důkladného sušení.","keywords":["jak dlouho","trva","hodin","suseni"]},{"question":"Vyzvednete auto u mě?","answer":"Ano, nabízíme pick-up & delivery v Olomouci a okolí – auto si po dohodě vyzvedneme u vás doma nebo v práci a vrátíme ho dokonale čisté.","keywords":["vyzvedn","pick up","pickup","odvoz","dovoz","kde","adresa"]},{"question":"Kdy máte otevřeno?","answer":"Otevírací doba je dle dohody – zavolejte na +420 797 859 558.","keywords":["oteviraci","otevreno","kdy mate","vikend"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '6a17c8b4e453f3dd592a8ddfd429ef4fb790306349a8a2b6e44759ca817cca32', true);
