select public.svc_sync_tenant('{"slug":"showcar-detailing","name":"Showcar Detailing","shortName":"Showcar","kind":"detailing","tagline":"Powłoki ceramiczne Fireball i folie ochronne PPF Llumar w Gdyni","description":"Nazywam się Marek Lachowicz i zajmuję się auto detailingiem od 2006 roku. Showcar Detailing to studio, które oficjalnie stworzyłem w 2015 roku – dziś to dwuosobowy team. Naszym głównym zajęciem jest renowacja i zabezpieczanie lakieru powłokami ceramicznymi i foliami ochronnymi PPF. Jesteśmy pierwszym akredytowanym studiem powłok Fireball w Trójmieście i pierwszym w województwie pomorskim akredytowanym studiem folii PPF Llumar.","locale":"pl-PL","timezone":"Europe/Warsaw","currency":"PLN","accentColor":"#B8BEC6","contacts":{"phone":"+48506698699","address":"ul. Hutnicza 47, 81-061 Gdynia","mapUrl":"https://g.page/ShowcarDetailing?share","instagram":"showcar_detailing","facebook":"ShowcarDetailingGdynia","email":"marek@showcar.pl"},"images":{"hero":"/s/showcar-detailing/media/hero.webp","logo":"/s/showcar-detailing/media/logo.png"},"hours":{"mon":[["09:00","18:00"]],"tue":[["09:00","18:00"]],"wed":[["09:00","18:00"]],"thu":[["09:00","18:00"]],"fri":[["09:00","18:00"]],"sat":[["09:00","18:00"]],"sun":[]},"closedDates":["2026-11-01","2026-11-11","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-01-06","2027-03-28","2027-03-29","2027-05-01","2027-05-03","2027-05-16","2027-05-27","2027-08-15","2027-11-01","2027-11-11","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":1440,"horizonDays":60,"cancelCutoffHours":48,"defaultBufferMinutes":60},"resources":[{"key":"stanowisko","name":"Stanowisko"}],"services":[{"key":"aegis","name":"Fireball Aegis (2 lata)","description":"Koreańska powłoka ceramiczna Fireball, trwałość 2 lata. Dla aut segmentu mini –10 %; auta z wieloma plastikowymi elementami i minivany wyceniamy indywidualnie. Cena netto.","category":"Powłoki ceramiczne","price":1200,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"devils-blood","name":"Fireball Devils Blood (3 lata)","description":"Koreańska powłoka ceramiczna Fireball, trwałość 3 lata. Dla aut segmentu mini –10 %; auta z wieloma plastikowymi elementami i minivany wyceniamy indywidualnie. Cena netto.","category":"Powłoki ceramiczne","price":1700,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"silla","name":"Fireball Silla (5 lat)","description":"Koreańska powłoka ceramiczna Fireball, trwałość 5 lat. Dla aut segmentu mini –10 %; auta z wieloma plastikowymi elementami i minivany wyceniamy indywidualnie. Cena netto.","category":"Powłoki ceramiczne","price":2200,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"butterfly","name":"Fireball Butterfly 9H (7 lat)","description":"Koreańska powłoka ceramiczna Fireball, trwałość 7 lat. Dla aut segmentu mini –10 %; auta z wieloma plastikowymi elementami i minivany wyceniamy indywidualnie. Cena netto.","category":"Powłoki ceramiczne","price":2500,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"butterfly-graphene","name":"Fireball Butterfly Graphene 9H (9 lat)","description":"Koreańska powłoka ceramiczna Fireball, trwałość 9 lat. Dla aut segmentu mini –10 %; auta z wieloma plastikowymi elementami i minivany wyceniamy indywidualnie. Cena netto.","category":"Powłoki ceramiczne","price":2900,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"dokdo","name":"Fireball Dokdo 9H (10 lat)","description":"Koreańska powłoka ceramiczna Fireball, trwałość 10 lat. Dla aut segmentu mini –10 %; auta z wieloma plastikowymi elementami i minivany wyceniamy indywidualnie. Cena netto.","category":"Powłoki ceramiczne","price":4000,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ppf","name":"Folia ochronna PPF Llumar z samoregeneracją","description":"Najlepsze zabezpieczenie lakieru: brak odprysków, samoregeneracja i maksymalny połysk. Od full front po oklejenie całego auta – zakres dobieramy indywidualnie. Cena netto.","category":"Folie PPF","price":4500,"priceFrom":true,"durationMinutes":4320,"resources":["stanowisko"]},{"key":"szyba-folia","name":"Folia ochronna przedniej szyby","description":"Maksymalne zabezpieczenie szyby czołowej – zapomnisz o odpryskach i pęknięciach. Cena netto.","category":"Folie PPF","price":1200,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"korekta","name":"Korekta lakieru / polerowanie","description":"Usuwanie mikrozarysowań i rys z powłoki lakierniczej, sfinalizowane jak największym połyskiem. Wycena zawsze indywidualna. Cena netto.","category":"Lakier i szyby","price":900,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"woskowanie","name":"Woskowanie lakieru","description":"Wycena zawsze indywidualna. Cena netto.","category":"Lakier i szyby","price":400,"priceFrom":true,"durationMinutes":240,"resources":["stanowisko"]},{"key":"hydrofob-przod","name":"Powłoka hydrofobowa – przednia szyba","description":"Niewidzialna wycieraczka na szybę czołową. Cena netto.","category":"Lakier i szyby","price":100,"priceFrom":false,"durationMinutes":60,"resources":["stanowisko"]},{"key":"hydrofob-wszystkie","name":"Powłoka hydrofobowa – wszystkie szyby","description":"Hydrofobowe zabezpieczenie wszystkich szyb. Cena netto.","category":"Lakier i szyby","price":300,"priceFrom":false,"durationMinutes":90,"resources":["stanowisko"]},{"key":"skora","name":"Zabezpieczanie tapicerki skórzanej","description":"Mniejsze brudzenie, łatwiejsze czyszczenie i przesunięta granica przetarć. Cena netto.","category":"Pielęgnacja","price":300,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"sprzedaz","name":"Przygotowanie do sprzedaży","description":"Polerowanie lakieru, odpryski, zarysowania parkingowe czy czyszczenie wnętrza – pakiet skrojony do Twojego auta. Wycena zawsze indywidualna. Cena netto.","category":"Pielęgnacja","price":400,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"mycie","name":"Bezpieczne mycie auta","description":"Dokładne mycie auta, nie powodujące zarysowań lakieru.","category":"Pielęgnacja","price":100,"priceFrom":true,"durationMinutes":90,"resources":["stanowisko"]},{"key":"ozon","name":"Ozonowanie wnętrza","description":"Dezynfekcja wnętrza: usuwanie bakterii, nieprzyjemnych zapachów i grzybów. Cena netto.","category":"Pielęgnacja","price":50,"priceFrom":false,"durationMinutes":30,"resources":["stanowisko"]},{"key":"silnik","name":"Czyszczenie komory silnika","description":"Wycena zawsze indywidualna. Nie czyścimy po usterkach olejowych. Cena netto.","category":"Pielęgnacja","price":100,"priceFrom":true,"durationMinutes":60,"resources":["stanowisko"]}],"infoCards":[{"icon":"shield","title":"Akredytacja Fireball i Llumar","text":"Pierwsze studio Fireball w Trójmieście i pierwsze w województwie pomorskim studio folii PPF Llumar."},{"icon":"car","title":"Auto zastępcze 0 zł","text":"Door2door dom–studio–dom od 0 zł, transport salon–studio–salon od 100 zł netto."},{"icon":"medal","title":"Od 2006 roku","text":"Doświadczenie zdobyte na setkach przeróżnych aut."}],"gallery":[{"image":"/s/showcar-detailing/media/work-gt3.webp","caption":"Porsche 911 GT3 Touring całe w folii PPF Llumar"},{"image":"/s/showcar-detailing/media/work-ferrari.webp","caption":"Ferrari 812 Superfast"},{"image":"/s/showcar-detailing/media/work-m3.webp","caption":"BMW M3 Competition – folia PPF i powłoka Fireball Butterfly"},{"image":"/s/showcar-detailing/media/work-bentley.webp","caption":"Bentley Continental GT oklejony w całości folią PPF Llumar"},{"image":"/s/showcar-detailing/media/work-r8.webp","caption":"Audi R8 RWD oklejone w całości folią PPF Llumar Valor"},{"image":"/s/showcar-detailing/media/work-defender.webp","caption":"Land Rover Defender – matowa folia PPF Llumar"},{"image":"/s/showcar-detailing/media/work-m4.webp","caption":"BMW M4 Competition Coupé – full body PPF"},{"image":"/s/showcar-detailing/media/work-bentayga.webp","caption":"Bentley Bentayga – korekta lakieru i powłoka Fireball Dokdo"},{"image":"/s/showcar-detailing/media/work-stelvio.webp","caption":"Alfa Romeo Stelvio Quadrifoglio – folia ochronna PPF"},{"image":"/s/showcar-detailing/media/work-x7.webp","caption":"BMW X7 – folia PPF Llumar Valor i powłoka Fireball Butterfly Graphene"},{"image":"/s/showcar-detailing/media/work-gts.webp","caption":"Porsche 911 GTS całe w folii PPF Llumar Valor"},{"image":"/s/showcar-detailing/media/work-xc60.webp","caption":"Volvo XC60 – full front PPF Llumar Valor i powłoka Fireball Butterfly"},{"image":"/s/showcar-detailing/media/work-cl55.webp","caption":"Mercedes-Benz CL55 AMG oklejony w całości folią PPF Llumar Valor"},{"image":"/s/showcar-detailing/media/work-rrover.webp","caption":"Range Rover Westminster – korekta lakieru i sprzątanie wnętrza"}],"faq":[{"question":"Czy ceny są netto?","answer":"Tak, ceny oznaczone w cenniku gwiazdką są cenami netto. Wycena w wielu przypadkach jest indywidualna, np. gdy auto ma wiele plastikowych elementów albo jest minivanem. Auta segmentu mini –10 %.","keywords":["netto","brutto","vat","faktur"]},{"question":"Czy dajecie auto zastępcze?","answer":"Tak, auto zastępcze za 0 zł. Oferujemy też door2door dom–studio–dom od 0 zł i transport salon–studio–salon od 100 zł netto.","keywords":["zastepcz","door","transport","odbior","salon"]},{"question":"Jaką powłokę ceramiczną wybrać?","answer":"Pracujemy na koreańskich powłokach Fireball: Aegis (2 lata, od 1200 zł), Devils Blood (3 lata, od 1700 zł), Silla (5 lat, od 2200 zł), Butterfly 9H (7 lat, od 2500 zł), Butterfly Graphene 9H (9 lat, od 2900 zł) i Dokdo 9H (10 lat, od 4000 zł). Najpopularniejszy zestaw to folia PPF z samoregeneracją + powłoka ceramiczna.","keywords":["jaka powlok","ktora powlok","wybrac","fireball","roznic"]},{"question":"Czy prowadzicie szkolenia?","answer":"Tak – z polerowania lakieru, powłok ceramicznych i folii ochronnych PPF. Szkolenia odbywają się w formule maksymalnie dwóch uczniów, z dużym naciskiem na praktykę.","keywords":["szkoleni","kurs","nauczyc"]},{"question":"Kiedy jesteście otwarci?","answer":"Od poniedziałku do soboty 9:00–18:00. Studio: ul. Hutnicza 47, Gdynia.","keywords":["otwarte","otwarci","godziny","sobot","gdzie","adres","hutnicz"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '93d465e74b3b1d34824704236cc3bb9ebaef4a380dc10601d9e7de4aab589d3e', true);
