select public.svc_sync_tenant('{"slug":"taubner-auto-detailing","name":"Taubner Auto Detailing","shortName":"Taubner","kind":"detailing","tagline":"Leštění světlometů a renovace autolaků v Praze 4 – Modřanech","description":"Specializujeme se na leštění světel a plexiskel, leštění a renovaci zašlých laků, údržbu a kompletní detailing automobilů a motocyklů. Za 17 let zkušeností jsme vyleštili přes 400 párů světel a přes 250 vozů, motocyklů a plastových dílů. Pracujeme s přípravky Rupes, Kamikaze Collection, Meguiar´s, Gyeon, Angelwax, Auto Finesse a 3M. Naším cílem je, aby byl výsledek vždy perfektní.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#E0202A","contacts":{"phone":"+420776243532","address":"Mezihorská 1329/20, 143 00 Praha 4 – Modřany","legalAddress":"Filip Taubner, IČ 71575049","mapUrl":"https://www.google.com/maps/search/?api=1&query=Mezihorsk%C3%A1%201329%2F20%2C%20Praha%204","instagram":"taubner_auto_detailing","facebook":"LesteniLaku","email":"filip.taubner@seznam.cz"},"images":{"hero":"/s/taubner-auto-detailing/media/hero.webp","logo":"/s/taubner-auto-detailing/media/logo.png"},"hours":{"mon":[["09:00","18:00"]],"tue":[["09:00","18:00"]],"wed":[["09:00","18:00"]],"thu":[["09:00","18:00"]],"fri":[["09:00","18:00"]],"sat":[["09:00","18:00"]],"sun":[["09:00","18:00"]]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":1440,"horizonDays":60,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"dilna","name":"Dílna"}],"services":[{"key":"svetla-par","name":"Leštění předních světlometů – pár","description":"Osobní automobily 1 300–1 600 Kč za pár dle náročnosti a velikosti světlometu. Bez demontáže, přímo na voze, i na počkání (cca 2–2,5 hod). V ceně 2 vrstvy kera