,"priceFrom":true,"durationMinutes":4320,"resources":["dilna"]},{"key":"lak-dil","name":"Leštění a voskování 1 dílu","description":"Cena za 1 díl, např. blatník, dveře nebo kapota.","category":"Renovace laku","price":900,"priceFrom":true,"durationMinutes":90,"resources":["dilna"]},{"key":"ker-lak","name":"Keramická ochrana laku – 3 vrstvy (12+ měsíců)","description":"Keramika GYEON na bázi SiO2: efekt nového laku, větší hloubka a lesk, vyšší odolnost proti poškrábání, UV a chemikáliím a lepší samočisticí schopnost. SUV a VAN +30 %.","category":"Keramika GYEON","price":12490,"priceFrom":true,"durationMinutes":1440,"resources":["dilna"]},{"key":"ker-plasty","name":"Keramika na vnější plasty, gumy a světla","description":"Keramická ochrana vnějších plastových a gumových částí a světel.","category":"Keramika GYEON","price":3800,"priceFrom":true,"durationMinutes":240,"resources":["dilna"]},{"key":"ker-skla","name":"Keramika na skla a zrcátka vč. leštění","description":"Keramická ochrana oken a zrcátek včetně leštění.","category":"Keramika GYEON","price":3950,"priceFrom":true,"durationMinutes":180,"resources":["dilna"]},{"key":"ker-disky","name":"Keramika na disky vč. leštění (4 ks)","description":"Keramická ochrana 4 disků včetně leštění.","category":"Keramika GYEON","price":6500,"priceFrom":true,"durationMinutes":240,"resources":["dilna"]},{"key":"ker-pneu","name":"Keramická ochrana a oživení pneumatik (4 ks)","description":"Keramická ochrana a oživení 4 pneumatik.","category":"Keramika GYEON","price":1600,"priceFrom":true,"durationMinutes":60,"resources":["dilna"]},{"key":"ker-strecha","name":"Keramika na textilní střechu kabrioletu","description":"Keramická ochrana textilní střechy kabrioletů.","category":"Keramika GYEON","price":4500,"priceFrom":true,"durationMinutes":180,"resources":["dilna"]},{"key":"ker-motor","name":"Keramika plastů motorového prostoru vč. čištění","description":"Čištění a keramická ochrana plastových částí motorového prostoru.","category":"Keramika GYEON","price":2200,"priceFrom":true,"durationMinutes":120,"resources":["dilna"]},{"key":"ker-textil","name":"Nano-hydrofobní ochrana textilu (1 sedadlo)","description":"Hydrofobní ochrana textilního sedadla.","category":"Keramika GYEON","price":800,"priceFrom":true,"durationMinutes":60,"resources":["dilna"]},{"key":"vosk-tekuty","name":"Tekutý vosk","description":"Aplikace tekutého vosku.","category":"Vosky a impregnace","price":950,"priceFrom":true,"durationMinutes":90,"resources":["dilna"]},{"key":"vosk-tuhy","name":"Tuhý vosk s příměsí karnauby","description":"Aplikace tuhého vosku s příměsí karnauby.","category":"Vosky a impregnace","price":1450,"priceFrom":true,"durationMinutes":120,"resources":["dilna"]},{"key":"sealant","name":"Polymerové vosky a sealanty","description":"Aplikace polymerového vosku nebo sealantu.","category":"Vosky a impregnace","price":2450,"priceFrom":true,"durationMinutes":150,"resources":["dilna"]},{"key":"vosk-disky","name":"Voskování disků (4 ks)","description":"Voskování 4 disků.","category":"Vosky a impregnace","price":1000,"priceFrom":true,"durationMinutes":60,"resources":["dilna"]},{"key":"motor","name":"Povrchové čištění motorového prostoru","description":"Čištění motorového prostoru, oživení plastů a hadic. Tlakové mytí motorů neprovádíme.","category":"Vosky a impregnace","price":1200,"priceFrom":true,"durationMinutes":90,"resources":["dilna"]},{"key":"pneu","name":"Oživení a impregnace pneumatik","description":"Oživení a impregnace pneumatik.","category":"Vosky a impregnace","price":600,"priceFrom":true,"durationMinutes":30,"resources":["dilna"]},{"key":"myti","name":"Ruční mytí metodou dvou věder","description":"Ruční mytí pH neutrálním šamponem s mycí rukavicí a metodou dvou věder + sušení.","category":"Exteriér","price":700,"priceFrom":true,"durationMinutes":90,"resources":["dilna"]},{"key":"dekont-disky","name":"Dekontaminace disků (4 ks)","description":"Chemická dekontaminace 4 disků.","category":"Exteriér","price":1800,"priceFrom":true,"durationMinutes":90,"resources":["dilna"]},{"key":"clay","name":"Dekontaminace laku (clay)","description":"Kompletní odstranění nečistot a vyčištění pórů laku.","category":"Exteriér","price":2600,"priceFrom":true,"durationMinutes":180,"resources":["dilna"]},{"key":"lesteni-disky","name":"Leštění lakovaných disků (4 ks)","description":"Příprava disků pro keramiku nebo voskování.","category":"Exteriér","price":4400,"priceFrom":true,"durationMinutes":240,"resources":["dilna"]},{"key":"celni-sklo","name":"Vyhlazení čelního skla + tekuté stěrače","description":"Vyhlazení čelního skla od drobných defektů a zaschlého znečištění, aplikace tekutých stěračů.","category":"Exteriér","price":1400,"priceFrom":true,"durationMinutes":90,"resources":["dilna"]},{"key":"miza","name":"Odstranění mízy ze stromů, asfaltu…","description":"Odstranění mízy, asfaltu a podobných nečistot.","category":"Exteriér","price":500,"priceFrom":true,"durationMinutes":60,"resources":["dilna"]},{"key":"koncovky","name":"Leštění chromových koncovek výfuků (2 ks)","description":"Leštění 2 chromových koncovek.","category":"Exteriér","price":700,"priceFrom":true,"durationMinutes":60,"resources":["dilna"]},{"key":"interier","name":"Suché čištění interiéru","description":"Suché vysátí interiéru, koberečků a kufru, čištění plastových částí a impregnace.","category":"Interiér a ostatní","price":1750,"priceFrom":true,"durationMinutes":180,"resources":["dilna"]},{"key":"kuze","name":"Čištění a impregnace kůže + interiér","description":"Čištění, ošetření a impregnace kůže, suché vysátí interiéru a kufru, čištění a impregnace plastů.","category":"Interiér a ostatní","price":3250,"priceFrom":true,"durationMinutes":240,"resources":["dilna"]},{"key":"klima","name":"Dezinfekce klimatizace a odstranění zápachu","description":"Dezinfekce klimatizace, odstranění zápachu a provonění interiéru.","category":"Interiér a ostatní","price":500,"priceFrom":false,"durationMinutes":60,"resources":["dilna"]},{"key":"prodej","name":"Kompletní příprava vozu na prodej","description":"Mytí, korekce laku, čištění interiéru a kufru, čištění motorového prostoru – cena dle dohody.","category":"Interiér a ostatní","price":0,"priceFrom":false,"durationMinutes":1440,"resources":["dilna"]},{"key":"skoleni","name":"Poradenství, individuální školení a konzultace","description":"Cena 900 Kč za hodinu.","category":"Interiér a ostatní","price":900,"priceFrom":false,"durationMinutes":60,"resources":["dilna"]}],"infoCards":[{"icon":"medal","title":"Best Detailing Awards","text":"Ocenění Best Detailing by Meguiar´s v letech 2012 a 2013."},{"icon":"sun","title":"400+ párů světel","text":"17 let zkušeností a přes 250 vyleštěných a vydetailovaných vozů."},{"icon":"shield","title":"Záruka 1 rok","text":"Na vyleštěné světlomety, chráněné 2 vrstvami keramiky GYEON."}],"gallery":[{"image":"/s/taubner-auto-detailing/media/svetla-1-2-after.webp","before":"/s/taubner-auto-detailing/media/svetla-1-2-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-3-4-after.webp","before":"/s/taubner-auto-detailing/media/svetla-3-4-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-9-10-after.webp","before":"/s/taubner-auto-detailing/media/svetla-9-10-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-11-12-after.webp","before":"/s/taubner-auto-detailing/media/svetla-11-12-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-15-16-after.webp","before":"/s/taubner-auto-detailing/media/svetla-15-16-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-17-18-after.webp","before":"/s/taubner-auto-detailing/media/svetla-17-18-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-21-22-after.webp","before":"/s/taubner-auto-detailing/media/svetla-21-22-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-25-26-after.webp","before":"/s/taubner-auto-detailing/media/svetla-25-26-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-27-28-after.webp","before":"/s/taubner-auto-detailing/media/svetla-27-28-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/svetla-29-30-after.webp","before":"/s/taubner-auto-detailing/media/svetla-29-30-before.webp","caption":"Renovace předního světlometu – před a po"},{"image":"/s/taubner-auto-detailing/media/work-fabia.webp","caption":"Leštění světlometů Škoda Fabia – reportáž pro SkodaHome.cz"},{"image":"/s/taubner-auto-detailing/media/work-bmw.webp","caption":"BMW – detailing laku"}],"faq":[{"question":"Kolik stojí leštění světel?","answer":"Jeden přední světlomet 650–800 Kč (1 300–1 600 Kč za pár) dle náročnosti a velikosti, u SUV a dodávek od 800 Kč za kus. Zadní svítilny 300–450 Kč za kus. V ceně jsou vždy 2 vrstvy keramiky GYEON Q2M Trim. Ceny jsou včetně DPH.","keywords":["kolik","cena","cenik","stoji"]},{"question":"Leštíte světla na počkání?","answer":"Ano. Renovace obou předních světel většinou zabere 2 až 2,5 hodiny, vše probíhá přímo na voze bez demontáže a celý proces můžete sledovat.","keywords":["pockan","jak dlouho","trva","hodin","demontaz"]},{"question":"Jakou dáváte záruku?","answer":"Na vyleštěné světlomety poskytujeme záruku 1 rok.","keywords":["zaruk","vydrz","jak dlouho vydrz"]},{"question":"Jak dlouho trvá renovace laku?","answer":"Leštění a renovace laku trvá 2 až 4 dny podle rozsahu poškození laku a velikosti auta.","keywords":["lak","renovac","lesten","dni","dny"]},{"question":"Platí ceny i pro SUV?","answer":"Všechny ceny jsou orientační, závisí na rozsahu poškození a velikosti vozu – u SUV a VAN +30 %. Ceny jsou uvedeny včetně DPH 21 %.","keywords":["suv","van","dph","priplat","orientac"]},{"question":"Kdy máte otevřeno?","answer":"Pondělí–neděle dle objednání. Najdete nás na adrese Mezihorská 1329/20, Praha 4 – Modřany.","keywords":["oteviraci","otevreno","kdy mate","kde","adresa","modrany"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '4bd86293a65735fbe52ce9fc4e37ffbfd1ee3054a3fcb358510eb957ca810ae7', true);
