select public.svc_sync_tenant('{"slug":"tokyo-detailing","name":"Tokyo Detailing Center","shortName":"Tokyo","kind":"detailing","tagline":"Преміум детейлінг-центр у самому серці Одеси – експерти з PPF-плівки","description":"Преміум детейлінг-центр у самому серці Одеси. Ми спеціалізуємося на професійному захисті автомобілів PPF-плівкою та преміальному детейлінгу: полірування, хімчистка, керамічні покриття, тонування та шумоізоляція. Кожен автомобіль проходить повний цикл робіт із максимальною увагою до деталей, професійними матеріалами й суворим дотриманням технології.","locale":"uk-UA","timezone":"Europe/Kyiv","currency":"UAH","accentColor":"#C8102E","contacts":{"phone":"+380636126545","address":"вул. Краснова 3, Одеса","mapUrl":"https://maps.app.goo.gl/GMM8ChicGXwTLYrt9","telegram":"+380636126545","whatsapp":"380636126545","instagram":"detailingtokyo"},"images":{"hero":"/s/tokyo-detailing/media/hero.webp","logo":"/s/tokyo-detailing/media/logo.png"},"hours":{"mon":[["09:00","19:00"]],"tue":[["09:00","19:00"]],"wed":[["09:00","19:00"]],"thu":[["09:00","19:00"]],"fri":[["09:00","19:00"]],"sat":[["09:00","19:00"]],"sun":[]},"closedDates":[],"booking":{"slotStepMinutes":30,"minLeadMinutes":240,"horizonDays":60,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"boks","name":"Бокс"}],"services":[{"key":"ppf-full","name":"PPF плівка – повний захист кузова","description":"Повне обклеювання кузова антигравійною плівкою: захист від сколів, подряпин і реагентів. Комплексне тонування та бронювання передньої частини – наша найпопулярніша комбінація.","category":"Антигравійний захист","price":0,"priceFrom":false,"durationMinutes":5760,"resources":["boks"]},{"key":"ppf-front","name":"PPF плівка – передня частина","description":"Бронювання передньої частини: капот, бампер, фари, крила й дзеркала.","category":"Антигравійний захист","price":0,"priceFrom":false,"durationMinutes":2880,"resources":["boks"]},{"key":"ppf-local","name":"PPF плівка – локальний захист","description":"Окремі елементи: фари, пороги, ніші ручок, зони під навантаженням.","category":"Антигравійний захист","price":0,"priceFrom":false,"durationMinutes":480,"resources":["boks"]},{"key":"korekciya","name":"Корекція лакофарбового покриття","description":"Машинне полірування кузова: усунення подряпин, голограм і тьмяності, глибокий блиск.","category":"Полірування","price":0,"priceFrom":false,"durationMinutes":1440,"resources":["boks"]},{"key":"optyka","name":"Полірування оптики","description":"Відновлення прозорості фар.","category":"Полірування","price":0,"priceFrom":false,"durationMinutes":120,"resources":["boks"]},{"key":"dysky-polir","name":"Полірування дисків","description":"Відновлення блиску колісних дисків.","category":"Полірування","price":0,"priceFrom":false,"durationMinutes":240,"resources":["boks"]},{"key":"himchystka","name":"Хімчистка салону","description":"Глибока чистка сидінь, стелі, підлоги та пластику салону.","category":"Хімчистка","price":0,"priceFrom":false,"durationMinutes":480,"resources":["boks"]},{"key":"ozon","name":"Озонування","description":"Дезінфекція салону озоном, усунення запахів.","category":"Хімчистка","price":0,"priceFrom":false,"durationMinutes":60,"resources":["boks"]},{"key":"kuzov","name":"Детейлінг-мийка кузова","description":"Безпечна детейлінг-мийка кузова з очищенням від бітуму й металевих вкраплень.","category":"Детейлінг","price":0,"priceFrom":false,"durationMinutes":180,"resources":["boks"]},{"key":"dvygun","name":"Детейлінг двигуна","description":"Чистка й консервація моторного відсіку.","category":"Детейлінг","price":0,"priceFrom":false,"durationMinutes":90,"resources":["boks"]},{"key":"dysky","name":"Детейлінг дисків","description":"Глибока чистка колісних дисків.","category":"Детейлінг","price":0,"priceFrom":false,"durationMinutes":90,"resources":["boks"]},{"key":"keramika","name":"Керамічне покриття","description":"Довготривалий захист лаку керамікою: гідрофобний ефект, блиск і стійкість до хімії.","category":"Захисні покриття","price":0,"priceFrom":false,"durationMinutes":2880,"resources":["boks"]},{"key":"leather-shield","name":"Leather Shield – захист шкіри","description":"Захисне покриття для шкіряних сидінь: від потертостей, плям і вигоряння.","category":"Захисні покриття","price":0,"priceFrom":false,"durationMinutes":180,"resources":["boks"]},{"key":"tonuvannia","name":"Тонування","description":"Тонування скла авто плівкою.","category":"Тонування","price":0,"priceFrom":false,"durationMinutes":300,"resources":["boks"]},{"key":"shumo-salon","name":"Шумоізоляція салону","description":"Комплексна шумо- та віброізоляція салону.","category":"Шумоізоляція","price":0,"priceFrom":false,"durationMinutes":2880,"resources":["boks"]},{"key":"shumo-dveri","name":"Шумоізоляція дверей","description":"Шумо- та віброізоляція дверей.","category":"Шумоізоляція","price":0,"priceFrom":false,"durationMinutes":480,"resources":["boks"]},{"key":"shumo-pidloga","name":"Шумоізоляція підлоги","description":"Шумо- та віброізоляція підлоги.","category":"Шумоізоляція","price":0,"priceFrom":false,"durationMinutes":1440,"resources":["boks"]}],"infoCards":[{"icon":"shield","title":"Експерти з PPF","text":"Повний і локальний антигравійний захист кузова."},{"icon":"medal","title":"7+ брендів-партнерів","text":"Gyeon, Kybertane, Polor, Brawix, Soft99, Car Detail Lab, Clif Designs."},{"icon":"sparkle","title":"Увага до кожної деталі","text":"Повний цикл робіт за суворою технологією – клієнти відзначають чистоту в студії."}],"gallery":[{"image":"/s/tokyo-detailing/media/work-m4.webp","caption":"BMW M4 – матовий PPF"},{"image":"/s/tokyo-detailing/media/work-ppf-bmw.webp","caption":"BMW – поклейка антигравійної плівки"},{"image":"/s/tokyo-detailing/media/work-ppf-bmw-2.webp","caption":"Повний антигравійний захист"},{"image":"/s/tokyo-detailing/media/work-polish.webp","caption":"Полірування Audi RS"},{"image":"/s/tokyo-detailing/media/work-engine.webp","caption":"Детейлінг двигуна Audi RS"},{"image":"/s/tokyo-detailing/media/work-wheel.webp","caption":"Детейлінг салону Audi"},{"image":"/s/tokyo-detailing/media/work-seats.webp","caption":"Чистка шкіряних сидінь"},{"image":"/s/tokyo-detailing/media/work-leather.webp","caption":"Leather Shield – захист шкіри"},{"image":"/s/tokyo-detailing/media/work-noise.webp","caption":"Шумоізоляція підлоги"}],"faq":[{"question":"Скільки коштують послуги?","answer":"Вартість залежить від авто та обсягу робіт – зателефонуйте або напишіть у месенджер, і ми підберемо оптимальний пакет: +380 63 612 65 45.","keywords":["скільки кошту","ціна","вартіст","прайс","пакет"]},{"question":"Повний чи локальний PPF?","answer":"Повний захист обклеює весь кузов, бронювання передньої частини захищає найбільш уразливі зони від сколів, а локальний – окремі елементи на кшталт фар чи порогів. Підкажемо, що підійде вашому авто.","keywords":["повний","локальн","яку плівку","передн"]},{"question":"Які матеріали ви використовуєте?","answer":"Лише сертифіковані матеріали та обладнання від світових лідерів: Gyeon, Kybertane, Polor, Brawix, Soft99, Car Detail Lab та Clif Designs.","keywords":["матеріал","бренд","gyeon","партнер","хімі"]},{"question":"Що таке Leather Shield?","answer":"Захисне покриття Gyeon для шкіряних сидінь: зберігає вигляд шкіри, захищає від потертостей, плям і вигоряння.","keywords":["leather","шкір"]},{"question":"Як записатися?","answer":"Оберіть послугу й вільний час тут на сайті або дзвоніть і пишіть у Telegram, WhatsApp чи Instagram – як вам зручніше.","keywords":["як записат","месенджер","telegram","viber","whatsapp"]},{"question":"Де ви знаходитесь?","answer":"Одеса, вул. Краснова 3. Телефон: +380 63 612 65 45.","keywords":["де ви","адрес","краснов","знаходит","доїхат"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'f1b2fae4f778e0fef36d24a1358d5567454e0d611f7b66f66e9bbc3dce524c0a', true);
