ion":"Wieloetapowe odkurzanie, czyszczenie plastików i zakamarków, czyszczenie skór lub pranie tapicerki i impregnacja całego wnętrza. Mały / średni / duży samochód: 650 / 700 / 800 zł netto.","category":"Detailing wnętrza","price":650,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"pranie-podlogi","name":"Pranie podłogi (bez demontażu foteli)","description":"Mały / średni / duży samochód: 300 / 350 / 400 zł netto.","category":"Detailing wnętrza","price":300,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"pranie-tapicerki","name":"Pranie tapicerki materiałowej","description":"Mały / średni / duży samochód: 250 / 300 / 400 zł netto.","category":"Detailing wnętrza","price":250,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"impregnacja-tapicerki","name":"Impregnacja tapicerki materiałowej","description":"Mały / średni / duży samochód: 200 / 250 / 350 zł netto.","category":"Detailing wnętrza","price":200,"priceFrom":true,"durationMinutes":90,"resources":["stanowisko"]},{"key":"podsufitka","name":"Czyszczenie podsufitki","description":"Mały / średni / duży samochód: 150 / 250 / 300 zł netto.","category":"Detailing wnętrza","price":150,"priceFrom":true,"durationMinutes":90,"resources":["stanowisko"]},{"key":"skora","name":"Czyszczenie i impregnacja elementów skórzanych","description":"Mały / średni / duży samochód: 300 / 350 / 450 zł netto.","category":"Detailing wnętrza","price":300,"priceFrom":true,"durationMinutes":180,"resources":["stanowisko"]},{"key":"ozon","name":"Ozonowanie","description":"Cena netto.","category":"Detailing wnętrza","price":150,"priceFrom":false,"durationMinutes":60,"resources":["stanowisko"]},{"key":"ppf-basic","name":"Pakiet PPF – BASIC","description":"Reflektory, wnęki klamek, próg załadunkowy zderzaka tylnego. Cena netto.","category":"Folie PPF i kolor","price":1200,"priceFrom":true,"durationMinutes":480,"resources":["stanowisko"]},{"key":"ppf-bikini","name":"Pakiet PPF – BIKINI","description":"Zderzak przedni, 1/3 maski i błotników przednich, reflektory, wnęki klamek, próg załadunkowy. Cena netto.","category":"Folie PPF i kolor","price":3200,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"ppf-full-front","name":"Pakiet PPF – FULL FRONT","description":"Zderzak przedni, maska, błotniki przednie, lusterka, słupki A, fragment dachu nad szybą, reflektory, wnęki klamek, ranty drzwi, próg załadunkowy. Cena netto.","category":"Folie PPF i kolor","price":5200,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"ppf-full-body","name":"Pakiet PPF – FULL BODY","description":"Pełne zabezpieczenie karoserii i lamp. Cena netto.","category":"Folie PPF i kolor","price":12500,"priceFrom":true,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"ppf-reflektory","name":"Folia PPF na reflektory","description":"Cena netto.","category":"Folie PPF i kolor","price":450,"priceFrom":true,"durationMinutes":120,"resources":["stanowisko"]},{"key":"wrapping","name":"Wrapping – zmiana koloru auta","description":"Wycena indywidualna. Także dechroming, usuwanie reklam i przyciemnianie szyb.","category":"Folie PPF i kolor","price":0,"priceFrom":false,"durationMinutes":7200,"resources":["stanowisko"]},{"key":"nowe-basic","name":"Auto nowe – pakiet BASIC","description":"Do 500 km przebiegu: mycie detailingowe, ceramika na lakier 1 rok, powłoka na szyby, felgi front, impregnacja skór/tapicerki, czernienie opon. Mały / średni / duży samochód: 1600 / 1800 / 2000 zł netto.","category":"Pakiety – auta nowe","price":1600,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"nowe-standard","name":"Auto nowe – pakiet STANDARD","description":"Jak BASIC, z powłoką ceramiczną na 3 lata. Mały / średni / duży samochód: 2100 / 2300 / 2500 zł netto.","category":"Pakiety – auta nowe","price":2100,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"nowe-premium","name":"Auto nowe – pakiet PREMIUM","description":"Jak BASIC, z powłoką ceramiczną na 5 lat. Mały / średni / duży samochód: 2700 / 2950 / 3200 zł netto.","category":"Pakiety – auta nowe","price":2700,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"silver","name":"Auto używane – pakiet SILVER","description":"Mycie z dekontaminacją, sprzątanie wnętrza, quick detailer na lakier i wnętrze, mycie szyb, czernienie opon. Mały / średni / duży samochód: 650 / 750 / 850 zł netto.","category":"Pakiety – auta używane","price":650,"priceFrom":true,"durationMinutes":300,"resources":["stanowisko"]},{"key":"gold","name":"Auto używane – pakiet GOLD","description":"Jednoetapowa korekta, ceramika na 1 rok, sprzątanie wnętrza, szyby, zaprawki i ozonowanie. Mały / średni / duży samochód: 2050 / 2350 / 2650 zł netto.","category":"Pakiety – auta używane","price":2050,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]},{"key":"gold-plus","name":"Auto używane – pakiet GOLD +","description":"Dwuetapowa korekta, ceramika na 3 lata, detailingowe sprzątanie wnętrza, ceramika na szyby, zaprawki, ozonowanie. Mały / średni / duży samochód: 3400 / 3700 / 4100 zł netto.","category":"Pakiety – auta używane","price":3400,"priceFrom":true,"durationMinutes":2880,"resources":["stanowisko"]},{"key":"platinum","name":"Auto używane – pakiet PLATINUM","description":"Pełna korekta, ceramika na 5 lat, pełny detailing wnętrza, felgi, szyby, komora silnika, zaprawki i ozonowanie. Mały / średni / duży samochód: 4600 / 5200 / 5850 zł netto.","category":"Pakiety – auta używane","price":4600,"priceFrom":true,"durationMinutes":4320,"resources":["stanowisko"]},{"key":"sprzedaz","name":"Przygotowanie auta do sprzedaży","description":"Mycie z dekontaminacją, jednoetapowa korekta, quick detailer, sprzątanie wnętrza, odtłuszczenie szyb. Mały / średni / duży samochód: 1150 / 1300 / 1450 zł netto.","category":"Pakiety – auta używane","price":1150,"priceFrom":true,"durationMinutes":1440,"resources":["stanowisko"]}],"infoCards":[{"icon":"car","title":"Door-to-Door gratis","text":"Odbiór i zwrot auta do 10 km bez dopłat."},{"icon":"shield","title":"PPF z 10-letnią gwarancją","text":"Folie z samoregeneracją – najlepiej zaraz po odbiorze auta z salonu."},{"icon":"clock","title":"Także poza godzinami","text":"Możesz umówić wizytę także poza godzinami pracy."}],"gallery":[{"image":"/s/zoom-detailing/media/work-superb.webp","caption":"Škoda Superb – tuning optyczny"},{"image":"/s/zoom-detailing/media/work-e350d.webp","caption":"Mercedes-Benz E 350d Cabrio"},{"image":"/s/zoom-detailing/media/work-xc90.webp","caption":"Volvo XC90"},{"image":"/s/zoom-detailing/media/work-bmw5.webp","caption":"BMW serii 5"},{"image":"/s/zoom-detailing/media/work-lbx.webp","caption":"Lexus LBX"},{"image":"/s/zoom-detailing/media/work-xc60.webp","caption":"Volvo XC60"},{"image":"/s/zoom-detailing/media/work-fiat500.webp","caption":"Fiat 500"},{"image":"/s/zoom-detailing/media/work-xc60-white.webp","caption":"Volvo XC60"},{"image":"/s/zoom-detailing/media/work-ppf.webp","caption":"Folia PPF na reflektory"},{"image":"/s/zoom-detailing/media/work-polerowanie.webp","caption":"Korekta lakieru"},{"image":"/s/zoom-detailing/media/work-ceramika.webp","caption":"Aplikacja powłoki ceramicznej"},{"image":"/s/zoom-detailing/media/work-s2000.webp","caption":"Czyszczenie skóry – Honda S2000"},{"image":"/s/zoom-detailing/media/work-studio.webp","caption":"Nasze studio w Wawrze"}],"faq":[{"question":"Czy ceny są netto?","answer":"Tak, ceny są w złotych netto – przy płatności należy doliczyć 23% VAT. Większość usług ma trzy ceny: dla małego, średniego i dużego samochodu.","keywords":["netto","brutto","vat","faktur","maly","duzy"]},{"question":"Czy odbieracie auto?","answer":"Tak – Door-to-Door do 10 km jest gratis.","keywords":["door","odbier","odwiez","transport","dowoz"]},{"question":"Czy trzeba się umawiać?","answer":"Tak, prosimy o umówienie się na wizytę – często realizujemy zlecenia poza siedzibą firmy. Można też umówić się poza godzinami pracy: pn.–pt. 9:00–17:00, sob. 10:00–14:00.","keywords":["umowi","wizyt","godzin","otwart","sobot","niedziel"]},{"question":"Kiedy najlepiej założyć folię PPF?","answer":"Rekomendujemy zabezpieczyć karoserię folią ochronną tuż po odbiorze samochodu z salonu. Folie mają samoregenerację i 10-letnią gwarancję producenta.","keywords":["kiedy","nowe auto","salon","gwarancj","ppf"]},{"question":"Obsługujecie firmy?","answer":"Tak – dla klientów B2B: tel. 450-150-850, e-mail biuro@zoomdetailing.pl.","keywords":["b2b","firm","flot","faktura vat"]},{"question":"Gdzie was znajdę?","answer":"Warszawa-Wawer, ul. Kombajnistów 3.","keywords":["gdzie","adres","kombajnist","wawer","dojazd"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'd0a8a7355ffe878addec289bb2f2c2cbbb024d610de207e0123b99ebe38d0a7b', true);
